/* المرحلة ٥: بناء الفارس (١٤–١٧ سنة) — عمّان · سيناريوهات كاملة */
window.SD.stages.push({id:5,icon:'🛡️',color:'#C0392B',name:'بناءُ الفارس',years:'١٤–١٧ سنة',place:'عمّان — الأردن',
intro:'سنوات المراهقة تتحول إلى سنوات بناء: ختم القرآن في الرابعة عشرة، إمامة التراويح، فتنة الشاشة، بطولة الرماية، ميلاد «جيل القدس» — ثم رحيل الجد ووصيته التي ترسم بقية الطريق.',
eps:[
{n:61,t:'يومُ الختمةِ الكبرى',ic:'👑',age:'١٤ سنة',loc:'المسجد الكبير — عمّان',corner:'quran',goal:'ختم القرآن كاملاً: تاج الكرامة لوالديه — والحفظ بداية مسؤولية لا نهايتها',chars:['صلاح الدين','الشيخ محمود','أيوب','مريم','لجنة الإجازة','صف الطامحين'],
scenes:[
{h:'م١ · خارجي — تحت الزيتونة، فجر اليوم الأخير',d:'فجر ذهبي في حديقة بيت الجد. صلاح الدين (١٤ سنة) يجلس تحت الزيتونة العتيقة، المصحف الأزرق (هدية الطائرة) مفتوح على آخر صفحاته، والجد بجانبه على كرسيه يسمع بعينين مغمضتين. أوراق الزيتون تتساقط ناعمة على الصفحة.',dlg:[['الجد','(هامساً بعد آخر آية) قل آمين… وأغلقْه. ما بقيَ حرفٌ لم يستقرَّ في صدرِك. أربعُ سنينَ من هذا الفجرِ يا صلاحَ الدين… واليومَ نقطفُ.'],['صلاح الدين','(يغلق المصحف ويده ترتجف قليلاً) جدي… رأسي فارغٌ فجأة. كأني نسيتُ كلَّ شيء!'],['الجد','(يضحك ضحكته المميزة) هذا هو الخوفُ المبارك — يعرفُهُ كلُّ حافظٍ صادق. اطمئن: القرآنُ لا يهربُ ممن أحبَّه أربعَ سنين. اليومَ لا تحملُهُ أنت… هو يحملُك.']],vo:'أربعُ سنين… ألفٌ وأربعُمئةِ فجر… من مسجدِ النورِ في مانشستر إلى زيتونةِ جدي في عمّان. واليومَ — وأنا في الرابعةَ عشرة — سأقفُ لأُسمِّعَ كتابَ اللهِ كاملاً. تذكرون طفلَ الألِفِ الأولى؟ ها هو ذا.'},
{h:'م٢ · داخلي — المسجد الكبير، مجلس الإجازة',d:'قاعة مهيبة: لجنة من ثلاثة شيوخ مجيزين خلف طاولة، والشيخ محمود بينهم بعينين رطبتين. المسجد ممتلئ — العائلة، والعصبة، وكريم، وصف الطامحين، وشاشة مرفوعة عليها الشيخ إدريس وتوم من مانشستر. صلاح الدين يجلس على ركبتيه أمام اللجنة، المفتاح على صدره تحت الثوب.',dlg:[['رئيس اللجنة','(بمهابة) الإجازةُ يا بني ليست حفلاً… إنها سندٌ يصلُ صدرَكَ برسولِ اللهِ ﷺ. سنفتحُ عليكَ من أماكنَ متفرقة. جاهز؟ اقرأ من قوله تعالى: «وما أرسلناكَ إلا رحمةً للعالمين»…'],['صلاح الدين','(يأخذ نفساً، يستعيذ، وينطلق بصوت هادئ واثق — يتنقل بين المواضع التي يفتحونها عليه بلا تعثر)'],['الشيخ محمود','(يهمس لرئيس اللجنة، ودمعة تلمع) اختبروه في المتشابهات… في «قالوا» و«وقالوا»، في مواضعِ السجود. أريدُ أن يعرفَ المسجدُ من هو.']]},
{h:'م٣ · داخلي — المسجد، سجدة الختم',d:'اللجنة تُنهي بسورة الناس. صلاح الدين يتلو «مِنَ الجِنَّةِ والناس» — ثم صمت. يطبق المصحف ببطء، يضعه على صدره، وينزل ساجداً. سجدة شكر طويلة صامتة — القاعة كلها تصمت معه، حتى الأطفال. الكاميرا تقترب: كتفاه ترتجفان، ودمعة تسقط على السجاد.',dlg:[['صلاح الدين','(همساً في سجوده، لا يسمعه إلا الميكروفون) الحمدُ لله… الحمدُ للهِ الذي بدأ بي طفلاً يشيرُ للمطرِ ويقولُ «الله»… وبلغَ بي هذا. اللهم اجعلْهُ حجةً لي لا عليّ.'],['رئيس اللجنة','(يرفع يديه بعد أن يرفع الفتى رأسه) بحمدِ اللهِ وتوفيقِه… نُجيزُ صلاحَ الدينَ بنَ أيوبَ بروايةِ حفصٍ عن عاصم، سنداً متصلاً إلى رسولِ اللهِ ﷺ. اللهُ أكبر!'],['المسجد','(تكبير يهز الجدران — وزغرودة الجدة، وتوم من الشاشة يصفق واقفاً)']]},
{h:'م٤ · داخلي — المسجد، تاج الوالدين',d:'الشيخ محمود يستدعي أيوب ومريم للمنصة. يقف بينهما ويده على كتف كل منهما.',dlg:[['الشيخ محمود','قال رسولُ اللهِ ﷺ: من قرأ القرآنَ وعملَ بما فيه، أُلبسَ والداهُ تاجاً يومَ القيامةِ ضوؤهُ أحسنُ من ضوءِ الشمس… فما ظنُّكم بمن حفظَهُ كلَّه؟ يا أيوب، يا مريم: هذا التاجُ الذي تلبسانِهِ اليومَ رمزاً… هو تاجٌ حقيقيٌّ يُدَّخَرُ لكما هناك. ثمرةُ الليالي التي أيقظتِهِ فيها يا مريم للورد… وسهرتَ فيها يا أيوب على مصروفِ الحلقة.'],['أيوب','(الرجل الهادئ الذي لم نره يبكي — تنهمر دمعتاه أمام ابنه لأول مرة، يعانق مريم بلا كلمات)'],['صلاح الدين','(من مكانه، يرى دموع أبيه — يهمس لنفسه) أبكيتُ أبي فرحاً… هذه أعظمُ جائزةٍ في الدنيا.']],vo:'رأيتُ أبي يبكي لأولِ مرةٍ في حياتي… فرحاً بي. وعرفتُ يومَها أن حفظَ القرآنِ ليس إنجازي وحدي — إنه هديةُ أمهاتٍ وآباءٍ حملوا معنا الجبل، درجةً بعد درجة.'},
{h:'م٥ · داخلي — المسجد، الكلمة القالبة',d:'الشيخ محمود يهدئ الفرح ويرفع يده — يريد أن يقول كلمة أخيرة، وجهه جاد فجأة.',dlg:[['الشيخ محمود','يا أهلَ المسجد… لا أريدُ لهذا الفتى أن ينامَ الليلةَ مطمئناً أنه «وصل». فاسمعْ يا صلاحَ الدين، وهذا أهمُّ ما ستسمعُهُ اليوم: حتى الأمسِ كان القرآنُ في صدرِك زينةً وفخراً. من اليوم… صار حجةً: إما لكَ وإما عليك! قال ﷺ: القرآنُ حجةٌ لكَ أو عليك. من حملَ كلامَ اللهِ ثم كذبَ، أو غشَّ، أو قطعَ فجراً، أو آذى جاراً — خاصمَهُ القرآنُ يومَ القيامة. الحفظُ يا بني ليس نهايةَ الطريق… إنه أولُ يومٍ في مسؤوليةٍ ثقيلة. لم تختمِ القرآن… القرآنُ ابتدأك.'],['صلاح الدين','(يقف، يمسك الميكروفون، يبتلع فرحه ويجدّ) شيخي… سمعتُها كأنها نزلتْ عليَّ وحدي. أعاهدُكَ والمسجدَ شاهد: لن أكونَ حافظاً يخاصمُهُ محفوظُه. سأعملُ به حرفاً حرفاً — أو أموتُ دونَ ذلك.']],vo:'«لم تختمِ القرآن… القرآنُ ابتدأك». نمتُ تلك الليلةَ والجملةُ تدقُّ في صدري كناقوس. وما زالت تدقُّ إلى اليوم. فيا كلَّ حافظٍ صغير: تاجُكَ جميل… لكنه ثقيل. احملْهُ بالعمل، لا بالفخرِ وحدَه.'}],
msg:'القرآن حجةٌ لك أو عليك: الحفظ ليس نهاية الطريق بل أول يوم في المسؤولية — ومن حمل كلام الله عمل به أو خاصمه.',apply:'مهما كان حفظك اليوم: حدد هدف ختمك الكبير واكتب السنة المستهدفة — واحسبها: كم صفحة في اليوم تكفي؟'},

{n:62,t:'إمامُ التراويحِ الصغير',ic:'🕌',age:'١٤ سنة',loc:'مسجد الحي — رمضان',corner:'ibada',goal:'حامل القرآن يتقدم: الإمامة تكليف ورهبة — والصوت الحسن نعمة تُستعمل لله',chars:['صلاح الدين','الشيخ محمود','الجد','أيوب','المصلون'],
scenes:[
{h:'م١ · داخلي — المسجد، التكليف المفاجئ',d:'ليلة أولى من رمضان، بعد العشاء. الشيخ محمود — تقدمت به السن وثقل صوته — يمسك كتف صلاح الدين بعد الصلاة.',dlg:[['الشيخ محمود','صوتي لم يعدْ يحملُ عشرين ركعة يا بني… وصدرُكَ يحملُ القرآنَ كلَّه. من الليلة، تصلي بالناسِ الجزءَ الأخيرَ من التراويح.'],['صلاح الدين','(تتسع عيناه ويتراجع خطوة) أنا؟! أؤمُّ الناس؟! يا شيخي فيهم جدي… وأبي… وأنتَ! كيف أتقدمُ على من علَّموني؟!'],['الشيخ محمود','(يبتسم) ولهذا بالذات اخترتُك — الإمامةُ ليست تشريفاً للأقدمِ يا صلاح الدين، بل تكليفاً للأحفظ. قال ﷺ: يؤمُّ القومَ أقرؤهم لكتابِ الله. وأنتَ الليلةَ أقرؤُهم. تقدمْ… وتوكل.']],vo:'رعشةٌ لم أعرفْها من قبل: أن أقفَ إماماً وخلفي جدي وأبي ومعلمي! في مانشستر كنتُ الطفلَ الذي يقلدُ حركاتِ المصلين… والليلةَ يقلدُ المصلون حركاتي! أثقلُ نعلين لبستُهما في حياتي.'},
{h:'م٢ · داخلي — المسجد، الليلة الأولى والخطأ',d:'صلاح الدين يتقدم المحراب، الصفوف خلفه. يكبّر بصوت مرتجف قليلاً ثم يثبت. يقرأ الفاتحة… ثم يبدأ سورة الرحمن. عند «فبأيِّ آلاءِ ربكما تكذبان» المكررة — يرتبك في ترتيب التكرار ويقف. صمت. من الصف الأول يفتح عليه الشيخ محمود بصوت خافت. يلتقطها ويكمل.',dlg:[['صلاح الدين','(بعد الصلاة، محبط، للشيخ) أخطأتُ أمامَ الجميع… في أولِ ليلة! خذلتُك يا شيخي.'],['الشيخ محمود','(يضحك بهدوء) خذلتَني؟! يا بني، أتدري لماذا شرعَ اللهُ الفتحَ على الإمام؟ ليعلمَنا أن الإمامَ بشرٌ يخطئ، وخلفَهُ أمةٌ تسندُه! لو كان الإمامُ معصوماً لاستغنى عن الصف. أخطأتَ فسندَكَ جدُّك وأبوك والصف — هذا جمالُ الجماعةِ لا عيبُها. عُدْ غداً أقوى.']]},
{h:'م٣ · داخلي — البيت، نصيحة الجد',d:'سطح البيت بعد التراويح. الجد وحفيده يشربان شاي رمضان. صلاح الدين ما زال متوتراً للغد.',dlg:[['صلاح الدين','جدي… وأنا أقرأ، أشعرُ بمئةِ عينٍ في ظهري. أفكرُ: هل صوتي جميل؟ هل يعجبُهم؟ فأنسى الآية!'],['الجد','(يضع الكوب) هذا داءُ الأئمةِ يا حبيبي، وله دواءٌ واحد: صلِّ بهم كأنكَ تصلي وحدَك بين يدي اللهِ في صحراءَ خالية. المئةُ عينٍ في ظهرِكَ لا تضرُّك… العينُ الوحيدةُ التي يجبُ أن تشغلَكَ هي عينُ اللهِ أمامَك. إن صلَّيتَ له وحدَه، خشعَ الناسُ خلفَك. وإن صلَّيتَ لهم، طردَكَ الخشوعُ أنتَ وإياهم.'],['صلاح الدين','(يتأمل النجوم)… أصلي كأني وحدي. حتى لو خلفي ألف؟'],['الجد','خاصةً لو خلفَكَ ألف. الإخلاصُ يا صلاح الدين… أن يكونَ سرُّكَ أجملَ من علنِك.']]},
{h:'م٤ · داخلي — المسجد، مونتاج الليالي',d:'مونتاج رمضاني: ليلة تلو ليلة — صوت صلاح الدين يثبت ويحلو، الصفوف تطول (انتشر خبر «الإمام الصغير الحافظ الخاشع»)، بكاء خافت في الصفوف عند آيات الرحمة، ويوسف الصغير يصف الأحذية عند الباب مقلداً أخاه أيام مانشستر. لقطة: امرأة عجوز تدعو له بعد الصلاة، ورجل يقول لابنه «تعلمْ منه».',vo:'ليلةً بعد ليلة، ثبتَ الصوتُ وامتلأ المسجد. وبدأتُ أشعرُ بشيءٍ خطيرٍ يتسللُ إلى قلبي: لذةُ أن يبكيَ الناسُ بصوتي… خطرٌ لا يفهمُهُ إلا من ذاقَه.'},
{h:'م٥ · داخلي — غرفته، مراقبة القلب',d:'ليلة السابع والعشرين، بعد قيام طويل أبكى المسجد. صلاح الدين في غرفته، منتشٍ قليلاً بثناء الناس. يقف أمام مرآته — ويرى في عينيه بريق العُجب فيرتبك.',dlg:[['صلاح الدين','(لنفسه في المرآة) قالوا: أبكيتَنا… قالوا: ما أجملَ صوتَك… (يتوقف فجأة، يتذكر كلمة جده) سرُّكَ أجملُ من علنِك… (يجلس على السرير محبطاً من نفسه) يا صلاحَ الدين — أبكيتَ الناسَ الليلة… فهل بكيتَ أنتَ لله؟ أم كنتَ تعدُّ إعجابَهم؟ (يرفع يديه) اللهم إني أعوذُ بكَ أن أُشركَ بكَ وأنا أعلم… طهِّرْ لي هذا الصوت، واجعلْهُ لكَ لا لهم، ولا تجعلْ حظّي منه ثناءَ الناسِ فأخسرَ الآخرة.'],['أيوب','(يطرق ويدخل، سمع آخر الدعاء) سمعتُك… أتدري أن هذا الدعاءَ أثقلُ في ميزانِكَ من كلِّ التراويح؟ الشيطانُ لا يخافُ الحافظَ الذي يقرأ… يخافُ الحافظَ الذي يحاسبُ قلبَه. نمْ يا بني — من راقبَ قلبَهُ هكذا، حُفظَ من العُجب.']],vo:'اكتشفتُ في تلك الليلةِ أن أصعبَ معركةٍ للحافظِ ليست حفظَ الحروف… بل حراسةَ القلبِ من أن ينتفخ. الصوتُ الحسنُ نعمةٌ يا أصدقائي — لكنها كالنار: تطبخُ لكَ إن ضبطتَها، وتحرقُكَ إن أطلقتَها. راقبوا قلوبَكم… فهي المعركةُ التي لا تنتهي.'}],
msg:'صلِّ بالناس كأنك وحدك بين يدي الله: الإخلاص أن يكون سرُّك أجمل من علنك — والصوت الحسن نار تطبخ أو تحرق.',apply:'إن كنت تحفظ فتقدم: أمّ إخوتك في صلاة جهرية بالبيت هذا الأسبوع — واستعذ من العجب قبلها وبعدها.'},

{n:63,t:'معلمُ الصغارِ في الخامسةَ عشرة',ic:'🧑‍🏫',age:'١٥ سنة',loc:'مسجد الحي',corner:'quran',goal:'«خيركم من تعلم القرآن وعلمه»: التعليم يثبّت العلم — والصبر على الصغار عبادة',chars:['صلاح الدين','الشيخ محمود','الطفل آدم','أطفال الحلقة','مريم (ذكرى)'],
scenes:[
{h:'م١ · داخلي — المسجد، إسناد الحلقة',d:'الشيخ محمود يقود صلاح الدين إلى ركن فيه ثمانية أطفال (٧–٩ سنوات) يعجّون كخلية.',dlg:[['الشيخ محمود','هؤلاء أمانتُك الجديدة — حلقةُ الصغار. من حفظَ القرآنَ عليه أن يعلمَه: قال ﷺ خيرُكم من تعلمَ القرآنَ وعلَّمه. علِّمْهم يا صلاح الدين.'],['صلاح الدين','(بثقة زائدة) سهلة يا شيخي! ثمانيةُ صغار؟ أنا أممتُ مئاتِ الرجالِ في التراويح!'],['الشيخ محمود','(يبتسم ابتسامة غامضة وهو ينصرف) نعم… نعم. سنتحدثُ بعد ساعة.']],vo:'ثمانيةُ صغار؟ ظننتُها استراحةً بعد إمامةِ المئات. بعد ساعةٍ واحدة… كنتُ قد فهمتُ لماذا ابتسمَ الشيخُ تلك الابتسامة.'},
{h:'م٢ · داخلي — الحلقة، الفوضى الأولى',d:'مشهد كوميدي حقيقي: صلاح الدين يحاول البدء — طفل يبكي لأن صديقه أخذ مكانه، طفل يشاغب ويقلّد صوت الإمام، طفل ثالث (آدم) يجلس صامتاً لا يفرّق الحاء من الخاء فيقرأ «الحمد» «الخمد»، ورابع يريد الحمام كل خمس دقائق. صلاح الدين يرفع صوته فيبكي اثنان. ينهار النظام.',dlg:[['صلاح الدين','(يائساً، يمسح جبينه) يا جماعة! اسكتوا! واحد… واحد فقط! (تزداد الفوضى)'],['الشيخ محمود','(يمر ويهمس ضاحكاً) الآن نتحدث؟ إمامةُ الرجالِ يا بني تحتاجُ صوتاً… وتعليمُ الصغارِ يحتاجُ قلباً. عدْ إلى معلمتِكَ الأولى — من علَّمَكَ أنت؟']]},
{h:'م٣ · داخلي — غرفته، استعادة أدوات الأم',d:'ليلاً. صلاح الدين محبط أمام مكتبه. تقع عيناه على صورة قديمة: هو طفلاً أمام «مكتب صلاح الدين» ولوحة الجبل التي رسمتها أمه. يبتسم، ويبدأ يكتب خطة.',dlg:[['صلاح الدين','(يكتب ويتذكر — نسمع صوت أمه من الماضي: «نحكي السورة قبل حفظها… نشجّع قبل نصحّح») أمي ما صرختْ فيَّ مرة… حكتْ لي حكاية، ورسمتْ لي جبلاً، ومدحتْ ألِفي المعوجّة! (يكتب) خطة الحلقة: قصةٌ قبل كل سورة… ولوحةُ جبلٍ لكل طفل… وتشجيعٌ قبل تصحيح… وآدم — (يتوقف) آدم يحتاجُ صبراً خاصاً.'],['مريم','(تطرق وتدخل بكوب حليب — كما كانت تفعل) ما زلتَ تسهر؟'],['صلاح الدين','(يريها الخطة) ماما… أنا أسرقُ طريقتَكِ في تربيتي! كيف صبرتِ عليَّ كلَّ تلك السنين؟'],['مريم','(تجلس، تبتسم) لأني ما رأيتُ فيكَ طفلاً يخطئ… رأيتُ رجلاً يتشكل. انظرْ لكلِّ صغيرٍ منهم هكذا… وسترى الصبرَ يأتي وحدَه.']]},
{h:'م٤ · داخلي — الحلقة، التحول',d:'مونتاج شهرين: صلاح الدين يفترش الأرض بينهم لا فوقهم. يحكي قصة الفيل بصوت الأصوات فتلتمع عيونهم. لكل طفل لوحة جبل صغيرة يلوّن درجتها. يخص آدم بعشر دقائق يومياً: يعلمه الحاء والخاء بلمس الحلق («ضع يدك هنا… أحسّها تهتز؟»). الفوضى تتحول نظاماً محبّاً — الأطفال يتسابقون للحضور مبكرين.',dlg:[['آدم','(بفخر عظيم) أستاذ صلاح الدين! الحَـمد لله! قلتُها صحيحة! الحاء!'],['صلاح الدين','(يرفعه عالياً) اللهُ أكبر يا آدم! سمعتم يا شباب؟ آدمُ فتحَ الحاء! (الحلقة تصفق)']]},
{h:'م٥ · داخلي — المسجد، ختمة آدم',d:'بعد شهرين: حفل صغير — آدم (أضعف تلاميذه) يختم سورة الفيل غيباً أمام أهله الذين جاؤوا خصيصاً. صلاح الدين واقف في الخلف يشاهد، وعيناه تلمعان أكثر من يوم ختمته هو.',dlg:[['والد آدم','(يصافح صلاح الدين متأثراً) ابني كان يكره الحلقة ويبكي كلَّ صباح… الآن يوقظُني للمسجد! ماذا فعلتَ به؟'],['صلاح الدين','(يبتسم) لا شيء… فقط نظرتُ إليه كما نظرتْ أمي إليّ. رأيتُ فيه لا الطفلَ الذي لا يفرّقُ الحروف… بل الحافظَ الذي سيصير.'],['الشيخ محمود','(يقترب) الآن فهمتَ سرَّ الحلقة يا صلاح الدين؟ يومَ ختمتَ أنت، بكى أبوك فرحاً بك. واليومَ… أنتَ تبكي فرحاً بغيرك. وهذه — واللهِ — درجةٌ أعلى: أن تكونَ فرحةُ تلميذِكَ بفتحِهِ أحلى في قلبِكَ من فتحِكَ أنت. هكذا يورَّثُ النور: لا يُكنَز… يُوزَّع.']],vo:'يومَ ختمتُ القرآنَ فرحتُ لنفسي… ويومَ ختمَ آدمُ سورةَ الفيلِ فرحتُ فرحاً أنقى وأعمق. عرفتُ أن العلمَ كالماء: إن حبستَهُ أسِنَ، وإن أجريتَهُ للناسِ عذُبَ وزاد. علِّموا يا أصدقائي… فالتعليمُ زكاةُ العلم.'}],
msg:'خيركم من تعلم القرآن وعلمه: التعليم زكاة العلم يثبّته ويطهّره — وفرحتك بفتح تلميذك أعلى من فرحتك بفتحك.',apply:'علّم اليوم من هو أصغر منك شيئاً تتقنه: سورة قصيرة، حرفاً، مهارة — واصبر عليه كما صُبر عليك.'},

{n:64,t:'ذهبُ الرماية',ic:'🎯',age:'١٥ سنة',loc:'بطولة المملكة للرماية',corner:'sport',goal:'التفوق بلا غرور: النصر من الله — والخصم أخ لا عدو',chars:['صلاح الدين','أبو فارس','المنافس فارس الشمالي','الجد','أيوب'],
scenes:[
{h:'م١ · خارجي — ميدان البطولة، أجواء المنافسة',d:'ميدان رماية وطني: رايات، مدرجات، متسابقون من كل المحافظات بأقواس احترافية. صلاح الدين وأبو فارس عند نقطة الإحماء. المنافس الأقوى — فتى طويل بقوس فاخر اسمه «فارس الشمالي» — يتباهى أمام الكاميرات.',dlg:[['أبو فارس','(يشد وتر قوس صلاح الدين) هذه بطولةٌ حقيقيةٌ يا بطل — مستوىً لم تجربْهُ. تذكرْ قاعدتَنا الوحيدة وانسَ الباقي.'],['صلاح الدين','السهمُ يذهبُ حيثُ يذهبُ القلب.'],['أبو فارس','فأينَ قلبُكَ الآن؟'],['صلاح الدين','(يغمض عينيه ثانية) مع الله… ثم مع الهدف. لا مع المدرجاتِ ولا مع قوسِ فارسٍ الفاخر.'],['أبو فارس','(يربت كتفه) إذن فُزتَ قبل أن ترمي.']]},
{h:'م٢ · خارجي — الميدان، الاستفزاز',d:'قبل الجولة النهائية، فارس الشمالي يقترب من صلاح الدين متعمداً.',dlg:[['فارس الشمالي','(بغرور) سمعتُ أنك «حافظ قرآن» و«إمام»… عجيب أن يضيّعَ شيخٌ صغيرٌ وقتَهُ في الرماية! قوسُكَ هذا رخيص… ويدُك سترتجفُ أمام الجمهور. لا عيبَ في المركزِ الثاني يا شيخ.'],['صلاح الدين','(يبتسم بهدوء تام — لا يرد الاستفزاز) بارك اللهُ في قوسِكَ الجميل يا فارس… ووفقنا اللهُ لأحسنِ رمي. (يستدير ويهمس لنفسه) أعوذُ بالله… لن أدعْهُ يسرقُ سكينتي. هو يريدُ أن يُغضبَني لترتجفَ يدي — درسُ أبي فارس: الغاضبُ يخطئ.']],vo:'أرادَ أن يشعلَني قبل الرمي — حيلةٌ قديمة. لكني تعلمتُ من المهرةِ «ريح» ومن حمزةَ في الملعب: من ملكَ غضبَهُ، ملكَ سهمَه. تركتُ استفزازَهُ يمرُّ كالريحِ على الصخر.'},
{h:'م٣ · خارجي — الميدان، الرميات الحاسمة',d:'الجولة النهائية بينهما. فارس الشمالي يرمي أولاً — رميات قوية لكن واحدة تنحرف قليلاً (غروره شدّه). دور صلاح الدين: يقف، يتنفس، «بسم الله»، يفرغ صدره من الجمهور ومن فارس — لا شيء إلا هو والهدف. سهم… في المركز. سهم آخر… في المركز. السهم الأخير الحاسم: صمت المدرجات، لقطة بطيئة للسهم يشق الهواء… ويستقر في قلب الهدف تماماً. صافرة الفوز.',dlg:[['المذيع','ذهبُ فئةِ الناشئين… لصلاحِ الدينِ أيوب! بفارقِ نقطةٍ واحدة!'],['صلاح الدين','(لا يقفز محتفلاً — يخرّ ساجداً سجدة شكر قصيرة في الميدان، ثم يقوم) الحمدُ لله… الحمدُ لله.']]},
{h:'م٤ · خارجي — منصة التتويج، لفتة المهزوم',d:'التتويج. صلاح الدين على المنصة، وفارس الشمالي في المركز الثاني — منكسر، عيناه على الأرض، صدمة الخسارة والغرور المكسور. صلاح الدين ينزل عن المنصة، يمشي إليه، يرفع يده عالياً، ويخرج سهماً من جعبته ويضعه في يده.',dlg:[['صلاح الدين','(للجمهور، رافعاً يد منافسه) رميتُهُ رميةً شريفة — النقطةُ التي فصلتْنا كانت حظاً من الله، لا فرقاً بيننا! (لفارس، هامساً) وهذا السهمُ لك — من جعبةِ من فاز اليوم فقط… أما غداً فمن يدري؟ خصمُ اليومِ أخو الغد.'],['فارس الشمالي','(يرفع رأسه مذهولاً، الاستفزاز والغرور يذوبان)… استفززتُكَ قبل الرمي… وترفعُ يدي وتهديني سهماً؟! أنا… أعتذرُ يا صلاح الدين. أيُّ مدرسةٍ خرّجتْك؟'],['صلاح الدين','مدرسةٌ اسمُها: الخُلقُ أثقلُ في الميزانِ من الذهب. تعالَ نتدربْ معاً — الرماةُ الحقيقيون قلة، ويجبُ أن نتعاون.']]},
{h:'م٥ · خارجي — بيت الجد، الميدالية على صدر الجد',d:'العودة. صلاح الدين يدخل حديقة البيت والميدالية في يده. الجد على كرسيه تحت الزيتونة. بدل أن يعلقها في رقبته، يركع أمام جده ويعلقها على صدره هو.',dlg:[['الجد','(مندهشاً) ما هذا؟ الذهبُ لك يا بطل — أنتَ من رمى!'],['صلاح الدين','رميتُ بيدٍ درّبتَها أنت يا جدي — من علَّمني أن الكائنَ الحيَّ يُكسَبُ بالثقة؟ ومن اشترى لي أولَ قوس؟ ومن قال: علِّموا أولادَكم الرماية؟ هذه بيدِكَ لا بيدي.'],['الجد','(تلمع عيناه، يمسك الميدالية على صدره) يا بني… أنا علَّمتُكَ الرمي. لكنكَ اليومَ علَّمتَني شيئاً: أن ترفعَ يدَ من استفزَّك، وتهديَ سهمَكَ لمن خصمَك. هذا… هذا لم أعلِّمْكَ إياه. من أين لك؟'],['صلاح الدين','(يبتسم) من الرجلِ الذي فتحَ القدسَ يا جدي… فأمَّنَ من قاتلوه. اسمي عندي مدرسة.'],['أيوب','(يراقب من بعيد، يهمس) الجدُّ يعلّمُ الحفيدَ الرمي… والحفيدُ يعلّمُ الجدَّ الرحمة. هكذا تكبرُ العائلات.']],vo:'ذهبُ الرمايةِ ما زالَ عندي… لكن الصورةَ الأغلى: ميداليةٌ على صدرِ جدي، وسهمٌ في يدِ خصمٍ صار صديقاً. الفوزُ يا أصدقائي يكشفُ معدنَك أكثرَ من الخسارة: فكم من فائزٍ خسرَ أخلاقَهُ على منصةِ التتويج.'}],
msg:'التفوق بلا غرور: النصر من الله فاسجد له، والخصم أخو الغد فارفع يده — فالخلق أثقل في الميزان من كل ذهب.',apply:'في أول فوز قادم لك (مباراة، مسابقة، درجة): قل «الحمد لله» قبل أي كلمة، وصافح خصمك أو زميلك بحرارة.'},

{n:65,t:'فتنةُ الشاشةِ الصغيرة',ic:'📵',age:'١٥ سنة',loc:'غرفته — عمّان',corner:'heart',goal:'معركة العصر: الهاتف خادم لا سيد — حمية القلب من إدمان الشاشات ومحقرات الذنوب',chars:['صلاح الدين','الشيخ محمود','معاذ','أيوب'],
scenes:[
{h:'م١ · داخلي — غرفته، الهاتف الأول',d:'صلاح الدين يفتح علبة هاتفه الأول (كافأه أبوه على الختمة والذهب). فرحة بريئة أول الأمر: يتصل بتوم، يصور الزيتونة لجدته، ينشئ مجموعة العصبة.',vo:'أعطوني مفتاحَ الدنيا كلِّها في كفي… ولم يحذّرْني أحدٌ أنه مفتاحٌ يفتحُ الجنةَ والنار معاً. بدأتُ بريئاً: اتصالٌ بتوم، صورةٌ لجدتي… ثم بدأتِ الشاشةُ الصغيرةُ تكبرُ حتى ابتلعتْ أيامي.'},
{h:'م٢ · داخلي — غرفته، مونتاج الانزلاق',d:'مونتاج مقلق بإيقاع متسارع: ليل أزرق الضوء على وجهه، إصبع يمرر بلا توقف مقاطع لا تنتهي، الساعة تقفز من ١١ إلى ٢ فجراً، مصحفه الأزرق مغلق مغبّر على الرف، لوحة الفجر على الجدار — أول مربع فارغ منذ سنوات… ثم ثانٍ… ثم ثالث. لقطة قاسية: المنبه يرن للفجر ويده تكتمه وهو نصف نائم، والمصحف يراقب من الرف.',dlg:[['أيوب','(يطرق صباحاً، يرى العيون الحمراء) فاتكَ الفجرُ ثالثَ مرةٍ يا صلاح الدين…'],['صلاح الدين','(محرج، يتجنب عينيه) سهرتُ قليلاً… أذاكر.'],['أيوب','(ينظر للهاتف على الوسادة… لا يقول شيئاً — يخرج بهدوء. صمته أثقل من عتاب)']]},
{h:'م٣ · داخلي — المسجد، مصارحة الشيخ لا موعظته',d:'صلاح الدين في الحلقة شارد، عيناه ذابلتان. الشيخ محمود يلحظ فيبقيه بعد الجميع. لا صراخ، لا تحطيم هاتف — يجلس بجانبه.',dlg:[['الشيخ محمود','عيناكَ يا بني… أين ذهبَ نورُهما؟ منذ أسابيعَ أراقبُ حافظاً يذبل.'],['صلاح الدين','(ينكسر) لا أعرفُ ماذا أصابني يا شيخي… أفتحُ الهاتفَ «دقيقة» فتصيرُ ساعتين! أنوي الوردَ فأجدُ نفسي أمرّرُ مقاطعَ تافهة! فاتني الفجرُ ثلاثاً… أنا؟! أبطالُ الفجرِ منذ السابعة؟!'],['الشيخ محمود','(بهدوء) اسمعْ حكمةً واحدةً واحفظْها: القلبُ إناء — ما ملأتَهُ سكنَه. إن ملأتَهُ نوراً أضاء، وإن تركتَهُ للتفاهةِ تسكبُ فيه ليلَ نهار… أظلمَ فطردَ النور. أنتَ لم تفعلْ كبيرةً يا صلاح الدين… لكنك تغرقُ في «محقّراتِ الذنوب» — قال ﷺ: إياكم ومحقراتِ الذنوب، فإنهنَّ يجتمعنَ على الرجلِ حتى يهلكنَه. ساعةٌ ضائعةٌ محقّرة… وساعةٌ… حتى ضاعَ الفجرُ الذي هو نورُ يومِك.'],['صلاح الدين','(يمسح وجهه) فماذا أفعل؟ أكسرُ الهاتف؟'],['الشيخ محمود','(يضحك) لا! الهاتفُ سكينٌ يا بني: يقطعُ لكَ الخبزَ ويجرحُ يدَك — والحلُّ ليس رميَ السكاكين، بل تعلُّمَ إمساكِها. اجعلْهُ خادمَك… لا سيدَك.']]},
{h:'م٤ · داخلي — غرفته، عهد الهاتف',d:'صلاح الدين على مكتبه ليلاً — يفتح دفتره ويكتب «عهداً» جديداً كعادته في القرارات الكبرى. مريم تمر وتراقب من الباب بصمت.',dlg:[['صلاح الدين','(يكتب ويقرأ) «عهدُ الهاتف — بيني وبين الله: لا شاشةَ بعد صلاةِ العشاء. لا هاتفَ في الفراشِ أبداً — مكانُهُ الليليُّ خارجَ الغرفة. ساعةُ قرآنٍ قبل أيِّ ساعةِ تصفح. حسابُ أرباحٍ وخسائرَ كلَّ جمعة: ماذا نفعني؟ وماذا سرقَ مني؟ والفجرُ… خطٌّ أحمر». (يعلق العهد على المكتب بجانب عهد المئذنة القديم)'],['مريم','(تدخل) عدتَ لعادتِكَ القديمة: تحاربُ نفسَكَ بالورقةِ والقلم.'],['صلاح الدين','هذه أخطرُ معاركي يا ماما… في الطفولةِ حاربتُ الغيرةَ والكذب — أعداءٌ واضحون. أما هذا (يرفع الهاتف) فعدوٌّ يلبسُ ثوبَ صديق: يعطيكَ ويأخذُ منك في آنٍ واحد.']]},
{h:'م٥ · داخلي — غرفته، قلب السلاح',d:'بعد أسبوعين: مونتاج التعافي — الفجر يعود، المصحف الأزرق يُنفض غباره ويُفتح، لوحة الفجر تمتلئ. ثم الخطوة الأذكى: صلاح الدين يجلس أمام هاتفه — لا ليتصفح، بل ليصوّر. ينشئ حساباً صغيراً باسم «فوائد جيل القدس»: أول منشور — مقطع دقيقة يشرح فيه فائدة من حلقة الشيخ.',dlg:[['معاذ','(عبر مكالمة، يرى المنشور) صلاح الدين! حوّلتَ الهاتفَ من عدوٍّ إلى منبر؟!'],['صلاح الدين','(يبتسم) درسُ الشيخ: الشاشةُ سكين. كنتُ أجرحُ بها نفسي… فقررتُ أن أقطعَ بها خبزاً للناس. الفتنةُ نفسُها يا معاذ — إن هربتَ منها لاحقتْك، وإن سخّرتَها خدمتْك. لن ننسحبَ من الميدانِ الذي فيه شبابُ الأمة… سندخلُهُ لنضيئَه.'],['معاذ','(يضحك) إذن سجِّلْني ثاني منشور — عندي فائدةٌ عن الصبر!']],vo:'من فتى غرِقَ في الشاشةِ ثلاثةَ أسابيع… إلى فتىً جعلَها منبراً لجيلِ القدس. لم أنتصرْ بكسرِ الهاتف — انتصرتُ بترويضِه، كما رُوِّضتِ المهرةُ «ريح». يا شبابَ زماني: هاتفُكم ليس عدوَّكم ولا صديقَكم… هو مرآةُ قلبِكم. املؤوا القلبَ نوراً… تصرِ الشاشةُ نوراً.'}],
msg:'القلب إناء ما ملأته سكنه: الهاتف خادم لا سيد — لا تكسر السكين بل تعلم إمساكها، وحوّل الفتنة إلى منبر.',apply:'اكتب «عهد هاتفك»: لا شاشة بعد العشاء ولا في الفراش، وساعة قرآن قبل ساعة تصفح — وعلقه حيث تراه.'},

{n:66,t:'ورثةُ بيتِ الحكمة',ic:'🔭',age:'١٦ سنة',loc:'النادي العلمي المدرسي',corner:'academy',goal:'العلم عبادة أمة: من الخوارزمي إلى الروبوت — نستعيد مقعدنا في مقدمة العلوم',chars:['صلاح الدين','أيوب','فريق الروبوت','المعلم المشرف'],
scenes:[
{h:'م١ · داخلي — مختبر النادي، الانضمام المتردد',d:'مختبر مدرسي فيه فريق يبني روبوتاً لمسابقة عربية. المعلم المشرف يدعو صلاح الدين للانضمام (يحتاجون عقلاً منظماً).',dlg:[['صلاح الدين','(متردد) أستاذ… أنا حافظُ قرآنٍ وطالبُ حلقة… ما شأني بالأسلاكِ والروبوتات؟ أخافُ أن يشغلَني هذا عن ديني.'],['أيوب','(في البيت مساءً، يسمع تردده) من قال إن العلمَ التجريبيَّ ضدُّ الدين يا صلاح الدين؟! أولُ آيةٍ نزلتْ «اقرأ» — اقرأ ماذا؟ الوحيَ والكون! الذي بنى مجدَ أمتِنا لم يكن الحفّاظَ وحدَهم… بل الحفّاظُ الذين كانوا أطباءَ وفلكيين ومهندسين. العلمُ كلُّهُ عبادةٌ إن أُريدَ به وجهُ اللهِ ونفعُ الناس. اذهبْ… وكنْ حافظاً يبني.'],['صلاح الدين','(يفكر) حافظٌ يبني…']],vo:'كدتُ أرفضُ ظناً أن العلمَ الدنيويَّ يسرقُني من ديني! يا لجهلِ من يفصلُ بينهما. علَّمَني أبي أن أمةً قرأتْ «اقرأ» ما كان لها أن تتخلفَ يوماً عن مختبرِ العالم.'},
{h:'م٢ · داخلي — المختبر، ليلة اليأس',d:'قبل أسبوع من المسابقة. الروبوت يتعطل للمرة الرابعة — ذراعه الميكانيكية لا تمسك الجسم بثبات. الفريق محبط، أحدهم يريد الانسحاب.',dlg:[['عضو الفريق','انتهينا. أربعُ محاولاتٍ والذراعُ ترتجفُ وتُسقطُ الكرة. سننسحبُ ونوفّرُ الإحراج.'],['صلاح الدين','(يتذكر — نموذج دورة الماء، عشرون محاولة) مهلاً… في الثامنةِ من عمري صنعتُ مطراً في مطبخِ بيتنا بعد عشرين محاولة. المحاولةُ الرابعة ليست فشلاً — إنها الرابعة فقط! لكن… (ينظر للذراع المرتجفة) نحتاجُ فكرةً جديدة، لا محاولةً مكررة.']]},
{h:'م٣ · داخلي — المختبر، جلسة التاريخ الملهمة',d:'صلاح الدين يحضر كتاباً من مكتبة أبيه ويعرض صوراً على شاشة المختبر — يحوّل اليأس إلى إلهام.',dlg:[['صلاح الدين','قبل أن ننسحب… تعرفوا على المهندسين الأصليين. (يعرض) هذا الخوارزمي: اسمُهُ صار «الخوارزميات» التي يعملُ بها حاسوبُكم الآن. وهذا ابنُ الهيثم: أسسَ علمَ الضوءِ بالتجربةِ لا التخمين، قبل الغربِ بقرون. وهؤلاء بنو موسى بنُ شاكر: كتبوا «كتابَ الحيل» — آلاتٌ تعملُ وحدَها قبل ألفِ سنة! انظروا هذه: قابضٌ ميكانيكيٌّ يمسكُ الأشياءَ بثباتٍ… باستخدامِ التوازنِ لا القوةِ وحدَها!'],['عضو الفريق','(ينتبه) لحظة… التوازن لا القوة؟ ذراعُنا ترتجفُ لأننا نزيدُ قوةَ القبض! لو أضفنا موازناً مثل فكرةِ بني موسى…'],['صلاح الدين','(يبتسم) أجدادُكم يحلّون مشكلتَكم من ألفِ سنة! لسنا نبدأ من الصفر… نحن نكملُ سلسلةً انقطعت.']]},
{h:'م٤ · داخلي — المختبر، السهر الجميل',d:'مونتاج سهر الفريق: يطبقون فكرة الموازن، فشل أول، تعديل، شاي وضحك في الليل، صلاح الدين يذكّرهم بوقت الصلاة فيصلون جماعة في زاوية المختبر ثم يعودون. الذراع ترتجف… ثم تثبت… وتمسك الكرة بثبات تام. صيحة فرح تملأ المختبر منتصف الليل.',dlg:[['المعلم المشرف','(يدخل صباحاً، يرى الروبوت يعمل) نجح؟! كيف؟ جربتُ معكم كلَّ الحلولِ الحديثة!'],['صلاح الدين','لم نجرّبِ الحلَّ القديم يا أستاذ… فكرةُ مهندسٍ عربيٍّ من القرنِ التاسع.']]},
{h:'م٥ · داخلي — منصة المسابقة، ورثة بيت الحكمة',d:'المسابقة العربية: فرق كثيرة، روبوتات متطورة. فريق صلاح الدين يفوز بجائزة الابتكار — لأصالة الحل. على منصة التتويج، يكشفون لوحة صنعوها ويلصقونها على جهازهم أمام الجميع: «ورثة بيت الحكمة».',dlg:[['رئيس اللجنة','فكرةٌ مدهشةٌ ومبتكرة… من أين استلهمتموها؟'],['صلاح الدين','(يمسك الميكروفون) من بيتِ الحكمةِ يا سيدي — مكتبةِ بغدادَ قبل ألفِ سنة. نحن لم نبتكرْ شيئاً جديداً… نحن تذكّرنا فقط من نكون. أمةٌ علَّمتِ الدنيا الأرقامَ والطبَّ والفلك… لا يجوزُ أن تجلسَ في آخرِ صفوفِ المختبرات. جئنا نستعيدُ مقعدَنا الأول.'],['المعلم المشرف','(للفريق) أتعرفون ما الأجمل؟ أنكم لم تفوزوا بجهازٍ فقط… فزتم بهوية. من عرفَ أن جدَّهُ كان أستاذَ العالم… لا يرضى لنفسِهِ أن يكونَ تلميذاً متأخراً.']]},
{h:'م٥·خ · داخلي — البيت، الخاتمة',d:'صلاح الدين يعيد الكتاب لمكتبة أبيه، ويضع بجانبه جائزة الابتكار.',dlg:[['أيوب','جائزةُ العلمِ بجانبِ إجازةِ القرآن… على رفٍّ واحد. هذا يا بني هو التوازنُ الذي أردتُهُ لك.'],['صلاح الدين','فهمتُها الآن يا بابا: الحافظُ الذي لا يبني… نصفُ مسلم. والمهندسُ الذي لا يعرفُ ربَّه… يبني قصوراً على رمل. جيلُ القدسِ يحتاجُ الاثنين معاً: قلبٌ يحفظ… وعقلٌ يبني.']],vo:'من ليلةِ يأسٍ في مختبر… إلى استعادةِ هوية. تعلمتُ أن أخطرَ ما يُقالُ لشابٍّ مسلم: «العلمُ للغربِ والدينُ لنا». كذبةٌ كبرى! العلمُ ميراثُنا سرقوهُ ونمنا عنه. فيا شبابَ الأمة: عودوا لمقاعدِ المختبرات… فهي مساجدُ أخرى، إن نويتم بها بناءَ الأمة.'}],
msg:'العلم ميراثنا لا ميراث غيرنا: الحافظ الذي لا يبني نصف مسلم، والمهندس بلا رب يبني على رمل — فاجمع القلب والعقل.',apply:'ابحث الليلة عن عالم مسلم واحد في مجال تحبه (طب، فلك، هندسة، رياضيات) واحكِ قصته غداً لصديق.'},

{n:67,t:'يومَ بكى معاذ',ic:'🤲',age:'١٦ سنة',loc:'بيت معاذ والمقبرة',corner:'heart',goal:'مواساة المصاب وفقه الجنازة: الأخ وقت الشدة — والموت واعظ لا يكذب',chars:['صلاح الدين','معاذ','حمزة','كريم','الجد'],
scenes:[
{h:'م١ · داخلي — حلقة الفجر، الخبر',d:'حلقة الفجر تسير معتادة… ثم يدخل رجل ويهمس في أذن الشيخ. الشيخ يتوقف، وجهه يتغير، يقطع الحلقة.',dlg:[['الشيخ محمود','(بصوت ثقيل) إنا للهِ وإنا إليهِ راجعون… يا أبنائي، أبو معاذٍ توفيَ منذ ساعةٍ — سكتةٌ مفاجئة. معاذ… (يبحث عنه فيجده لم يأتِ بعد) لم يعلمْ بعد. من الأقربُ إليه؟'],['صلاح الدين','(يقف مصعوقاً، والعصبة تلتفت إليه) أنا وحمزة… سنذهبُ إليه الآن.'],['حمزة','(شاحباً) وماذا نقولُ له؟ ماذا يُقالُ لمن ماتَ أبوه فجأة؟!'],['صلاح الدين','(يتجمد — لا يعرف الجواب حقاً)… لا أعرف يا حمزة. لأولِ مرةٍ في حياتي… لا أعرفُ ماذا أقول.']],vo:'واجهنا في تلك السنِّ عدواً لم نواجهْهُ من قبل — لا يُصارَعُ ولا يُحاوَر: الموت. ولأولِ مرةٍ في حياتي، أنا الذي عندي جوابٌ لكلِّ موقف… وقفتُ فارغَ اليدين واللسان.'},
{h:'م٢ · خارجي/داخلي — بيت معاذ، درس الحضور',d:'صلاح الدين وحمزة على باب بيت معاذ. صلاح الدين يتردد، يستعيد كلمة سمعها. يدخلان فيجدان معاذ محطماً بين المعزّين. صلاح الدين لا يخطب — يذهب مباشرة ويحتضنه بصمت طويل.',dlg:[['معاذ','(بين البكاء) صلاح الدين… راح. أبي راح. كلَّمتُهُ البارحةَ وضحكْنا و… راح.'],['صلاح الدين','(لا يقول «لا تحزن» ولا «كل شيء سيكون بخير» — يحتضنه فقط، ثم يهمس) أنا هنا. نحن هنا. لن نتركَك.'],['حمزة','(يجلس على الأرض بجانبهما صامتاً، يضع يده على كتف معاذ)']],vo:'أردتُ أن أقولَ كلاماً عظيماً يواسيه… فتذكرتُ وصيةَ النبيِّ ﷺ: من كان يؤمنُ باللهِ واليومِ الآخرِ فليقلْ خيراً أو ليصمت. تعلمتُ يومَها أعمقَ درسٍ في المواساة: الحضورُ أبلغُ من الكلام. القلبُ المكسورُ لا يحتاجُ خطبةً… يحتاجُ كتفاً.'},
{h:'م٣ · خارجي — الجنازة والمقبرة، رهبة تربّي',d:'الجنازة. صلاح الدين يمشي في الصف، ثم يحمل النعش مع الحاملين (أول مرة). المقبرة: الصمت، التراب، الدعاء. الجد حضر متوكئاً، يقف بجانب حفيده عند القبر ويهمس درساً.',dlg:[['صلاح الدين','(هامساً للجد، مرتجفاً) جدي… القبرُ صغير. والدنيا كلُّها تنتهي في هذا؟'],['الجد','(بهدوء) نعم يا حبيبي. كلُّ ما نركضُ خلفَهُ — المالُ والجاهُ واللعب — يقفُ عند هذه الحفرة. لكن انظرْ: يدخلُ معه ثلاثة، ويرجعُ اثنان — أهلُهُ ومالُهُ يرجعان، ويبقى عملُه. نحن أبناءُ الآخرةِ يا صلاح الدين… ومن عاشَ لها، لم يُضِعْ دنياه؛ ومن عاشَ للدنيا وحدَها، خسرَ الاثنتين. زُرِ القبورَ يا بني — فهي أصدقُ واعظٍ لا يكذب.'],['صلاح الدين','(ينظر للتراب يُهال)… إذن كلُّ ما أبنيه يجبُ أن يعبرَ هذا القبرَ معي: القرآن، والعلم، والصدقة، والجيل. الباقي… يبقى فوق.']]},
{h:'م٤ · داخلي — بيت معاذ، أسبوع الوفاء الصامت',d:'مونتاج أسبوع كامل — العصبة تتكفل ببيت معاذ بلا إعلان: حمزة يشتري الخبز فجراً ويوصله، صلاح الدين يدرّس إخوة معاذ الصغار ويراجع معه دروسه ليلحق بالمدرسة، كريم يأتي بكعك أمه، معاذ يصلي بأمه وإخوته فيصير رجل البيت. لا أحد يذكر ما فعلوه — الصدقة الخفية.',dlg:[['أم معاذ','(لصلاح الدين وهو يخرج بعد تدريس الصغار) يا بني… أنتم حملتُم عنا الأسبوعَ الأثقلَ في حياتِنا. بماذا أدعو لكم؟'],['صلاح الدين','(محرج) لا شيءَ يا خالتي… معاذ أخونا، وبيتُهُ بيتُنا. ادعي فقط أن يثبّتنا اللهُ على هذا حتى نلقاه.']]},
{h:'م٥ · خارجي — سطح البيت، معاذ يعود',d:'بعد أسبوعين. العصبة على السطح. معاذ — أنضج، أهدأ، فيه حزن ساكن — يكسر صمته.',dlg:[['معاذ','أريدُ أن أشكرَكم… لا على الخبزِ والدروس. بل لأنكم لم تقولوا لي كلاماً فارغاً. جلستم معي وصمتُّم معي وبكيتُم معي. تعلمتُ منكم كيف تكونُ الأخوّة… في الشدةِ لا في السهرات.'],['صلاح الدين','هذا عهدُنا يا معاذ من ليلةِ توقيعِهِ على هذا السطحِ نفسِه: لا نتخاذلُ عن بعضِنا مهما كبرتِ المواقف. وأكبرُ موقفٍ… هو الموت.'],['معاذ','(ينظر للنجوم) أبي علَّمني الصلاة… وأنتم علّمتموني الصبر. وأنا الآن رجلُ بيتي. أعينوني.'],['صلاح الدين','(يمسك كتفه) نحن جميعاً رجالُ بيتِك. والآن — قم، أمَّنا في المغربِ الليلة. أبوكَ يفرحُ في قبرِهِ أن يرى ابنَهُ إماماً.']],vo:'كبرْنا في ذلك الأسبوعِ سنواتٍ دفعةً واحدة. الموتُ يا أصدقائي معلمٌ قاسٍ لكنه صادق: يريكَ حقيقةَ الدنيا في لحظة، ويريكَ من هم إخوانُكَ الحقيقيون. زوروا مرضاكم، وشيّعوا موتاكم، وواسوا مكسوريكم… فيومَ تُكسَرون، ستعرفون قيمةَ كتفٍ يُسنِد.'}],
msg:'الحضور أبلغ من الكلام: القلب المكسور يحتاج كتفاً لا خطبة — ونحن أبناء الآخرة، والموت واعظ لا يكذب.',apply:'واسِ مصاباً هذا الأسبوع: زيارة أو اتصال أو خدمة صامتة — وقل: «إن لله ما أخذ وله ما أعطى فلتصبر ولتحتسب».'},

{n:68,t:'أولُ دينارٍ حلال',ic:'💰',age:'١٦ سنة',loc:'معصرة الزيتون — قرب عمّان',corner:'social',goal:'الكسب الحلال شرف: عرق اليد أطيب الرزق — وأداء العمل بإتقان أمانة',chars:['صلاح الدين','صاحب المعصرة أبو الطيب','زميل العمل','مريم'],
scenes:[
{h:'م١ · خارجي — معصرة الزيتون، أول يوم',d:'صيف. معصرة زيتون قريبة من بيت الجد — رائحة زيت طازج، صناديق زيتون مكدسة، ماكينات تدور. صلاح الدين (١٦) يبدأ عملاً صيفياً بدل الفراغ. صاحب المعصرة أبو الطيب — رجل مهيب بمريول ملطخ بالزيت — يستقبله.',dlg:[['أبو الطيب','ابنُ الحاجِّ عبد القادر رحمه الله يريدُ أن يعمل؟ أهلاً وسهلاً! لكن اعلمْ: هنا لا محاباةَ لأحد — العملُ عملٌ، والأجرُ على قدرِ الإتقان. القاعدةُ الوحيدة معلقةٌ هناك (يشير للوحة: «من غشَّنا فليسَ منا»). ابدأ بنقلِ تلك الصناديق.'],['صلاح الدين','(ينظر لجبل الصناديق، يشمّر) بسم الله!']],vo:'ظننتُ أني عرفتُ التعبَ في التدريبِ والحفظِ والامتحانات. ثم رفعتُ أولَ صندوقِ زيتونٍ تحت شمسِ تموز… وعرفتُ أن للرزقِ الحلالِ طعماً آخر: طعمَ العرقِ الذي يسيلُ على الجبين.'},
{h:'م٢ · خارجي — المعصرة، وعورة الرزق',d:'مونتاج يوم عمل شاق: صناديق ثقيلة، شمس حارقة، يد تتقرح، زبون صعب يشكو من كل شيء، وقفة صلاة الظهر في زاوية المعصرة ثم العودة. صلاح الدين يتعلم أن المال لا يُجنى من فراغ.',dlg:[['زميل العمل','(في استراحة، يمسح عرقه) متعبٌ صحيح؟ أولُ أسبوعٍ دائماً الأصعب. لكن الراتبَ آخرَ الشهرِ يُنسي التعب.'],['صلاح الدين','(يتأمل يديه المتقرحتين) أبي يعطيني مصروفاً بلا تعب… لماذا شعرتُ الآن أن ديناراً واحداً من هذا أثمنُ من مصروفِ شهر؟'],['زميل العمل','لأنه دينارُك أنت — صنعتْهُ يداك. الرزقُ الذي تتعبُ فيه، تحبُّهُ وتحفظُه.']]},
{h:'م٣ · خارجي — المعصرة، إغراء الكسب السريع',d:'الزميل نفسه يقترب همساً بعرض «مربح».',dlg:[['زميل العمل','اسمعْ… عندي طريقةٌ لكسبٍ أسرعَ من هذا العرقِ كلِّه: تاجرٌ يريدُ من يبيعُ زيتَهُ «المخلوط» على أنه زيتٌ بكرٌ صافٍ — عمولةٌ سخية لمن يقنعُ الزبائن. أنتَ ابنُ عائلةٍ محترمة، كلامُكَ مسموع… ما رأيك؟'],['صلاح الدين','(يتوقف عن العمل، يمسح جبينه، يبتسم بهدوء) أتذكرُ لوحةَ أبي الطيب على الجدار؟ «من غشَّنا فليسَ منا». وأنا أذكرُ رجلاً في سوقِ الجمعةِ اسمُهُ أبو أحمد قال لي: الرزقُ لا ينقصُهُ الصدق. عمولتُكَ السريعةُ هذه يا صاحبي… نارٌ سريعة. أفضّلُ ديناري البطيءَ الحلالَ على قنطارِكَ الحرام. وانصحُك: اترك هذا التاجرَ قبل أن يحرقَك.'],['زميل العمل','(محرج)… أنتَ فعلاً ابنُ حلقةٍ! حسناً حسناً — نسيتُ الأمر.']]},
{h:'م٤ · خارجي — المعصرة، شهادة أبي الطيب',d:'آخر الشهر. أبو الطيب يسلمه راتبه الأول في ظرف، وينظر إليه نظرة تقدير.',dlg:[['أبو الطيب','سمعتُ بما رفضتَه… العرضَ المغشوش. (يضع يده على كتفه) يا بني، أنا في هذه المعصرةِ من ثلاثين سنة، ورأيتُ شباباً كثيرين تكسرُهم أولُ عمولةٍ حرام. أنتَ رفضتَها وأنتَ في السادسةَ عشرة وتحتاجُ المال. هذا راتبُك… وهذه زيادةٌ ليست على العمل — على الأمانة. من أمِنَ على دينارٍ… أُمِنَ على قنطار.']]},
{h:'م٥ · داخلي — البيت، تقسيم الدينار وهدية الأم',d:'صلاح الدين على مكتبه، الظرف أمامه، يفتح دفتره ويقسم راتبه الأول أمام الكاميرا.',dlg:[['صلاح الدين','(يعدّ ويقسم إلى ثلاث) العُشرُ صدقة — أول ما يخرج، تطهيرٌ وبركة. وهذا… (يفرد جزءاً) لأمي — هديةٌ من عرقِ يدي. والباقي ادخارٌ لمشروعِ جيلِ القدس. (يمسك حصة أمه ويخرج)'],['مريم','(يهديها الظرف الصغير) ما هذا؟'],['صلاح الدين','أولُ هديةٍ أشتريها لكِ من مالٍ تعبتُ فيه بنفسي… لا من مصروفٍ أعطاني إياهُ أبي. اشتريتُ لكِ به زجاجةَ عطرٍ كنتِ تحبينها.'],['مريم','(تفتحه، تحتضن الزجاجة، دمعتان) يا بني… أنفقتُ عليكَ ستةَ عشرَ عاماً ولم أنتظرْ مقابلاً… وهذه الزجاجةُ الصغيرة أغلى عندي من كنوزِ الدنيا. لأنها ثمنُ عرقِك… ووفاءُ قلبِك. باركَ اللهُ لكَ في رزقِك.']],vo:'أولُ دينارٍ حلالٍ في حياتي… قسمتُهُ ثلاثاً كما علمتني حصالةُ الدراجةِ في مانشستر: لله، ولمن أحب، ولمشروعِ الغد. وتعلمتُ أن اليدَ التي تتعبُ في الحلال… يصافحُها اللهُ بالبركة. اكسبوا حلالاً يا شباب… ولو قليلاً بطيئاً؛ فالقليلُ الطيبُ يبارَكُ، والكثيرُ الخبيثُ يُمحَق.'}],
msg:'عرق اليد أطيب الرزق: من أُمن على دينار أُمن على قنطار — والقليل الحلال يُبارَك والكثير الحرام يُمحَق.',apply:'اكسب أول مالك الحلال: خدمة بأجر رمزي (تنظيم مكتبة، مساعدة جار) — وقسّمه: صدقة وهدية وادخار.'},

{n:69,t:'ليلةُ العُرس',ic:'💍',age:'١٦ سنة ونصف',loc:'عرس ابن العم — عمّان',corner:'heart',goal:'الحياء تاج الشباب: غض البصر عز لا حرمان — والفرح الحلال أجمل الأفراح',chars:['صلاح الدين','أيوب','حمزة','معاذ','كريم','ابن العم العريس'],
scenes:[
{h:'م١ · داخلي — البيت، استعداد ووصية',d:'ثوب جديد وعطر (زجاجة أمه!). صلاح الدين وأبوه في السيارة نحو عرس ابن العم. أول مناسبة اجتماعية ضخمة يحضرها فتىً بالغاً.',dlg:[['أيوب','أولُ عرسٍ تحضرُهُ رجلاً لا طفلاً… فخذْ وصيةً قصيرة: العرسُ فرحٌ مشروعٌ نفرحُ به كاملاً — فيه الدفُّ والإنشادُ والطعامُ والضحك، هذه سنة. لكن الفرحَ يا بني له سياج: نفرحُ بالطيبِ لا بالمحرم، ونصونُ العينَ فيما لا يحل.'],['صلاح الدين','وكيف أصونُ العينَ في عرسٍ مزدحم؟'],['أيوب','غضُّ البصرِ يا صلاح الدين ليس أن تُغمضَ عينيكَ عن الدنيا كلِّها — بل أن ترفعَ همتَكَ عما لا يحلُّ لك، فتصرفَ نظرَكَ أولَ ما يقع. النظرةُ الأولى لك، والثانيةُ عليك. والحياءُ يا بني… تاجُ الشباب: من لبسَهُ صغيراً، حماهُ اللهُ كبيراً.']]},
{h:'م٢ · داخلي — قاعة العرس، فقه الفرح',d:'قاعة أفراح مبهجة (قسم رجال): زينة، دف وإنشاد، طعام، ضحك. صلاح الدين يرى الفرح النظيف الكامل — لا شيء محرم، وكل شيء بهجة.',dlg:[['كريم','(مندهشاً بجمال العرس) في المخيمِ أعراسُنا بسيطة… لكن هذا الفرحَ نفسُه! سبحان الله، ما احتاجوا حراماً ليفرحوا!'],['صلاح الدين','هذا بالضبطُ ما يظنُّهُ الناسُ خطأً يا كريم: أن الفرحَ الكاملَ يحتاجُ محرماً! انظرْ — دفٌّ وإنشادٌ وطعامٌ وإخوةٌ مجتمعون… فرحٌ حتى آخرِه، وحلالٌ حتى آخره. من قال إن الالتزامَ عبوس؟']]},
{h:'م٣ · داخلي — القاعة، موقف البصر',d:'لحظة اختبار رقيقة بلا تشنج: عند مدخل القاعة تمر مجموعة، ويقع بصر صلاح الدين مصادفة على ما لا ينبغي. يصرف نظره فوراً بتلقائية من تعوّد — يشغل عينه بمصافحة كريم، بلا افتعال ولا تشنج ولا لفت انتباه.',dlg:[['حمزة','(لاحظ الحركة الطبيعية، هامساً) صرفتَ نظرَكَ بسرعةٍ وسلاسة… وكأنها عادة.'],['صلاح الدين','(هامساً) لأنها عادةٌ يا حمزة — درّبتُها من عهدِ الهاتف. العينُ عضلة: إن عوّدتَها الانصرافَ عن الحرام، انصرفتْ وحدَها بلا معركة. والذي يترك النظرَ للهِ… يعوّضُهُ اللهُ حلاوةً يجدُها في قلبِه. جرّبْها ولا تناقشْني — ستشكرُني.'],['حمزة','(يبتسم) أنتَ لا تعظُني أبداً… فقط تعطيني «تمارين».'],['صلاح الدين','لأن الأخلاقَ يا صديقي تمارين… لا محاضرات.']]},
{h:'م٤ · داخلي — القاعة، فقرة الفتيان',d:'العريس (ابن العم) يطلب من الشباب فقرة. العصبة الأربعة يقودون فقرة إنشاد ودبكة — حماس نظيف يشعل القاعة. صلاح الدين ينشد بصوته الحافظ، والجميع يدبك في دائرة، والعريس في الوسط. فرح صاخب بريء.',dlg:[['العريس','(يعانق صلاح الدين لاهثاً من الدبكة) يا ابنَ العم! أنتم أشعلتُم عرسي! من قال إن أولادَ الحلقاتِ ثقيلو الظل؟!'],['صلاح الدين','(يضحك) نحن نفرحُ لفرحِكَ يا غالي… فرحاً يحبُّهُ الله! وادعُ لنا أن يرزقَنا اللهُ مثلَ ليلتِك — بيتاً يبدأُ بالبركة.']]},
{h:'م٥ · خارجي — خارج القاعة، خاطرة الختام',d:'نهاية الليل. صلاح الدين يخرج مع أبيه، القاعة تفرغ خلفهما.',dlg:[['أيوب','كيف وجدتَ أولَ أعراسِك؟'],['صلاح الدين','(يتأمل) وجدتُ أن الحلالَ واسعٌ يا بابا… أوسعُ مما يظنُّ الحزانى الذين يبحثون عن فرحِهم في الحرام. فرحنا الليلةَ كلَّ الفرح — وخرجنا وقلوبُنا بيضاء، لا نخجلُ من شيءٍ فعلناه.'],['أيوب','(يبتسم) وهذا يا بني سرُّ فرحِ المؤمن: أنه يفرحُ ثم ينام قريرَ العين. أما فرحُ الحرام… فيتبعُهُ صباحُ ندم.'],['صلاح الدين','(يهمس وهو ينظر للنجوم) يوماً ما يا بابا… سيكونُ لي بيتٌ يبدأُ هكذا: بالبركة. وسأبني بيتي كما بنيتَ بيتَنا — على «حكايةٍ وآيةٍ ودعاء».']],vo:'خرجتُ من أولِ أعراسي وأنا أفهمُ لماذا شرعَ اللهُ الفرحَ وحدّه: الفرحُ الحلالُ يملأُ القلبَ ويتركُهُ نظيفاً… والحرامُ يملأُ اللحظةَ ويتركُ القلبَ خرِباً. الحياءُ يا شبابَ زماني ليس حرماناً… إنه تاجٌ، وأنبلُ ما في الفتى أن يلبسَهُ وهو قادرٌ على خلعِه.'}],
msg:'الحياء تاج الشباب: غض البصر عزٌّ لا حرمان، والعين عضلة تعتاد الانصراف — والفرح الحلال يملأ القلب ويتركه نظيفاً.',apply:'احفظ قاعدة العين: «غضُّ البصر عزّ» — وفي أي شاشة أو شارع، حوّل نظرك عن الحرام فوراً واشغله بذكر.'},

{n:70,t:'الليلةُ التي غيّرتْه',ic:'✨',age:'١٧ سنة',loc:'المسجد — ليلة القدر',corner:'ibada',goal:'ليلة القدر مفصل عمر: الدعاء يصنع التاريخ — وقرارات الليل الكبرى تولد في السجود',chars:['صلاح الدين','الله (مناجاة)','شخصيات السلسلة (في الدعاء)'],
scenes:[
{h:'م١ · داخلي — المسجد، نية القيام الكامل',d:'ليلة سابع وعشرين، رمضان. صلاح الدين (١٧) يقرر تحدياً روحياً صامتاً: قيام الليل كله لأول مرة في عمره — من العشاء إلى الفجر. يجلس في زاويته المعتادة، المصحف الأزرق والدفتر، والمفتاح على صدره.',vo:'قررتُ في تلك الليلةِ أمراً لم أجرّبْهُ من قبل: أن أقومَ الليلَ كلَّه — لا جزءاً منه. لا أعرفُ ما الذي دفعني… ربما شعورٌ أن شيئاً كبيراً يقتربُ في حياتي، وأني أحتاجُ أن ألقى ربي وحدي قبلَه. كانت — بحقٍّ — الليلةَ التي غيّرتْني.'},
{h:'م٢ · داخلي — المسجد، مونتاج الليل',d:'مونتاج ليلي طويل بإضاءة الشموع الخافتة: ركعات طويلة، سجود يطول، تلاوة متهجدة، دموع. الساعة تتقدم — ١٢… ٢… ٣. المصلون يتناقصون ويبقى القليل. صلاح الدين وحده في زاويته، بين قيام وقعود وبكاء.',dlg:[['صلاح الدين','(في سجود طويل، يبكي) اللهم إني قصّرتُ… حافظٌ لكتابِك ويفوتُني الخشوع، إمامٌ بالناسِ ويداخلُني العُجب، صاحبُ عهودٍ وأنكثُ بعضَها. اغفرْ لي يا رب… وطهّرْ قلبي… واجعلْ ما بقيَ من عمري خيراً مما مضى.']]},
{h:'م٣ · داخلي — المسجد، جولة الدعاء الكبرى',d:'الثلث الأخير. صلاح الدين يرفع يديه ويفتح دفتر الأسماء — دعاء طويل مفصل، تمر فيه كل شخصيات السلسلة (تظهر وجوههم في ومضات مع كل دعاء).',dlg:[['صلاح الدين','(يعلو صوته تدريجياً) اللهم أمي مريم وأبي أيوب — اجزِهما عني خيرَ ما جزيتَ والداً عن ولد، وأدخلْهما الجنةَ بلا حساب… اللهم جدي عبد القادر — أطلْ عمرَهُ على طاعتِك، وأقرَّ عينَهُ ببيتِهِ قبل أن يلقاك… اللهم يوسف وشام — احفظْهما واجعلْهما لي عوناً على الخير… اللهم توم في مانشستر — يا مقلبَ القلوب، ثبّتْ قلبَهُ على الحقِّ الذي بدأ يقرؤه… اللهم كريم وأهلُ المخيمِ وأهلُ غزة — فرّجْ كربَهم وارزقهم عودةً عزيزة… (صوته يتهدج ويقبض على المفتاح) واللهم… القدس. يا اللهُ يا اللهُ يا الله — أرِنا فتحَها قبل أن نموت، واكتبْنا من جندِها، واجعلْ هذا المفتاحَ الذي على صدري يدورُ يوماً في بابِه.']]},
{h:'م٤ · داخلي — المسجد، السجدة الفاصلة',d:'السجدة الأخيرة قبيل الفجر. الكاميرا تقترب — لحظة صفاء ووضوح. في سجوده تتبلور رؤية حياته كلها فجأة، بوضوح لم يعرفه من قبل.',dlg:[['صلاح الدين','(في سجوده، همساً، والوضوح ينبثق) يا رب… عرفتُ. عرفتُ الآن ماذا أفعلُ بعمري. سأدرسُ الهندسة… لا لأبنيَ لنفسي بيتاً، بل لأبنيَ لأمتي مدارسَها ومساجدَها وبيوتَها. وسأكرّسُ حياتي لجيلِ القدس — أبني الجيلَ الذي يستحقُّ أن تُفتَحَ على يديهِ الأبواب. هذا عملي… هذه رسالتي. فبارِكْها يا رب، وأعنّي عليها، ولا تجعلني ممن يعرفُ الطريقَ ولا يمشيه.'],['الفجر','(أذان الفجر يرتفع في اللحظة نفسها التي يرفع فيها رأسه من السجود — كأن السماء تؤمّن على دعائه)']],vo:'في تلك السجدة، قبيلَ الفجر، رأيتُ حياتي كلَّها بوضوحِ النهار: مهندسٌ يبني، ومربٍّ يصنعُ جيلاً، وحاملُ مفتاحٍ ينتظرُ بابَه. لم تكن رؤيا في منام… كانت قراراً في سجود. وأصدقُ القراراتِ يا أصدقائي… تلك التي تُتَّخذُ وجبهتُكَ على الأرض.'},
{h:'م٥ · داخلي — غرفته، سطر الفجر المؤرخ',d:'صباح العيد يقترب. صلاح الدين في غرفته بعد الفجر، متعب مضيء. يفتح دفتره ويكتب قرار الليلة ويؤرخه — كما وثّق كل قرارات عمره الكبرى.',dlg:[['صلاح الدين','(يكتب ويقرأ) «ليلة القدر — ١٧ سنة. قرارُ العمر: أدرسُ الهندسةَ لأبنيَ للأمة، وأكرّسُ حياتي لجيلِ القدس حتى يفتحَ اللهُ به أو بمن بعدَه. كُتبَ في سجودٍ قبيلَ الفجر… واللهُ عليه شهيد». (يضع الدفتر بجانب عهد المئذنة، وينظر من النافذة للفجر الجديد)'],['أيوب','(يطرق، يحمل تمر السحور الأخير) قمتَ الليلَ كلَّه… رأيتُ نورَكَ من تحتِ الباب. ما الذي كتبت؟'],['صلاح الدين','(يريه الدفتر) طريقي يا بابا… رسمتُهُ الليلةَ كلَّه. أدرسُ الهندسة، وأبني جيلَ القدس.'],['أيوب','(يقرأ، تلمع عيناه، يقبّل رأسه) يا بني… انتظرتُ سبعةَ عشرَ عاماً لأرى ابني يختارُ طريقَهُ بنفسِه، لا لأني اخترتُهُ له. اليومَ اطمأنَّ قلبي… باركَ اللهُ خطاك.']],vo:'من تلك الليلة، ما عادَ في حياتي «ربما» ولا «لعل». صار لي طريقٌ واضح، وقرارٌ مؤرخٌ في دفتر. فيا من يبحثُ عن طريقِه: قم ليلةً كاملةً بين يدي الله… واسألْه. فالليلةُ التي تخلو فيها به صادقاً… قد تكونُ الليلةَ التي تغيّرُ عمرَكَ كلَّه.'}],
msg:'أصدق القرارات تُتخذ والجبهة على الأرض: ليلة تخلو فيها بالله صادقاً قد تغير عمرك — والدعاء يصنع التاريخ.',apply:'في قيامك القادم اصنع «جولة دعاء»: سمِّ أهلك وأصدقاءك واحداً واحداً بحاجاتهم — ثم ادعُ للأقصى دعاءً مفصلاً.'},

{n:71,t:'حطينُ تدخلُ الصف',ic:'📜',age:'١٧ سنة',loc:'مدرسته — حصة التاريخ',corner:'fortress',goal:'التاريخ وقود لا حنين: قصة حطين والفتح — كيف وحّد صلاح الدين الأمة قبل أن يحرر القدس',chars:['صلاح الدين','معلم التاريخ','زملاء الصف'],
scenes:[
{h:'م١ · داخلي — الصف، رتابة الحصة',d:'حصة تاريخ عن الحروب الصليبية. المعلم يملي تواريخ بصوت رتيب، الطلاب يكتبون بلا روح، بعضهم ينعس. اسم «صلاح الدين الأيوبي» يمر في سطر واحد كأنه رقم.',dlg:[['معلم التاريخ','(بملل) …وفي سنة ٥٨٣ هجرية، انتصر صلاح الدين في معركة حطين، ثم استعاد القدس سنة ٥٨٣… احفظوا التواريخ فهي في الامتحان.'],['صلاح الدين','(يرفع يده) أستاذ… أتأذنُ لي بخمسِ دقائق؟ أعددتُ عرضاً صغيراً عن حطين. أظنُّها تستحقُّ أكثرَ من سطرٍ وتاريخ.'],['معلم التاريخ','(مندهش، ينظر لساعته) عرض؟… حسناً، تفضل. لكن خمس دقائق فقط.']],vo:'كان اسمي يمرُّ في حصةِ التاريخِ كرقمٍ يُحفَظ للامتحان… واسمي هذا يا أصدقائي ليس رقماً. فاستأذنتُ المعلمَ — وأخرجتُ من حقيبتي خريطةً رسمتُها بيدي.'},
{h:'م٢ · داخلي — الصف، السرد المشتعل',d:'صلاح الدين يعلّق خريطته المرسومة يدوياً ويحكي — لا يُملي، يروي كأنه عاشها. الصف يستيقظ تدريجياً، النائمون يعتدلون.',dlg:[['صلاح الدين','تخيلوا الأمةَ قبل صلاح الدين: (يشير للخريطة الممزقة إمارات) دويلاتٌ صغيرةٌ متناحرة، أميرٌ يقاتلُ جارَهُ المسلمَ ويتحالفُ مع المحتل! والقدسُ محتلةٌ منذ ٨٨ سنة، ذُبحَ أهلُها يومَ سقوطِها حتى قالوا: خُضنا في الدمِ إلى الركب. فماذا فعلَ صلاح الدين؟ (يتوقف) هنا المفاجأة: لم يبدأ بمحاربةِ المحتل! بدأ بتوحيدِ الأمة — مصرَ والشامَ والجزيرة، مدينةً مدينة، عشرين سنة من الصبرِ والدبلوماسيةِ والحرب، حتى صارتِ الأمةُ الممزقةُ… يداً واحدة.']]},
{h:'م٣ · داخلي — الصف، ذروة حطين والفتح',d:'صلاح الدين يصل ذروة القصة — الصف كله منتبه تماماً الآن، لا نائم واحد.',dlg:[['صلاح الدين','وفي حطين — بذكاءِ القائد — حاصرَهم بعيداً عن الماءِ في حرِّ تموز، فأنهكهمُ العطشُ قبل السيف. ثم تقدّمَ نحو القدس. والآن أهمُّ جزء — انتبهوا: يوم دخلها المحتلُّ قبلَ ٨٨ سنة، ذبحوا كلَّ من فيها. فلما فتحها صلاح الدين… ماذا فعل برأيكم؟ (الصف يترقب) عفا! أمّنَ الناسَ على أرواحِهم، وحرسَ كنائسَهم بنفسِه، وأطلقَ آلافَ الأسرى، وحين رأى الفقراءَ يبكون عجزاً عن الفدية، دفعَ عنهم من مالِه! حتى المؤرخون الغربيون كتبوا: ما عرفَ الشرقُ فاتحاً أرحمَ منه. هذه — يا أصدقائي — قوةُ المسلم: يملكُ أن ينتقم… فيرحم.']]},
{h:'م٤ · داخلي — الصف، السؤال المدوي',d:'صلاح الدين يختم — لا بمعلومة، بل بسؤال يقلب الحصة كلها.',dlg:[['صلاح الدين','آخرُ كلمة: صلاح الدين لم يبدأ بالسيفِ ضدَّ العدو… بدأ بتوحيدِ قلوبِ أمتِه. المحتلُّ لم يهزمْهُ سلاحٌ متفوق… هزمَتْهُ أمةٌ اجتمعت بعد أن تفرقت. فأسألُكم — ونحن اليوم أمةٌ ممزقةٌ كما كانت قبله — بماذا نبدأ نحن؟ بالبكاء على القدس؟ أم بما بدأ به: توحيدِ القلوب، وبناءِ الجيل، أولاً؟'],['الصف','(صمت مطبق… ثم همهمة نقاش تشتعل — لأول مرة في حصة تاريخ)'],['معلم التاريخ','(يقف ببطء، متأثراً) اجلس يا صلاح الدين… (يلتفت للصف) هذه — واللهِ — أفضلُ حصةِ تاريخٍ دخلتُها في عشرين سنةَ تدريس. لأن هذا الفتى لم يعلّمكم تاريخاً… علّمكم كيف يصيرُ التاريخُ مرآةً وخطة. من أينَ لك هذا يا بني؟'],['صلاح الدين','من اسمي يا أستاذ… ومن جدٍّ حملَ مفتاحاً.']]},
{h:'م٥ · داخلي — الصف بعد الحصة، الأثر',d:'الطلاب يحيطون به بأسئلة — تغير حقيقي. أحدهم يسأل عن كتاب يقرؤه، آخر يسأل عن «جيل القدس».',dlg:[['زميل','صلاح الدين… أين أقرأ هذه القصةَ كاملة؟ وهذا «جيل القدس» الذي ذكرتَه — كيف أنضم؟'],['صلاح الدين','(يبتسم) القصةُ في كتبِ التاريخِ الحقيقيةِ لا في سطرِ الامتحان — سأعيرُك كتاباً. أما جيلُ القدس… (يخرج ورقة صغيرة) نلتقي كلَّ خميسٍ على سطحِ بيتِ جدي: قرآنٌ ورياضةٌ وتاريخٌ وعملُ خير. تعالَ — المقاعدُ لمن يريدُ أن يكونَ من جيلِ الأبواب، لا من جيلِ البكاء.'],['زميل','(يأخذ الورقة) الخميسَ القادم… أنا معكم.']],vo:'دخلتْ حطينُ حصةَ التاريخِ سطراً للحفظ… وخرجتْ منها شرارة. وانضمَّ لجيلِ القدسِ في ذلك الأسبوعِ ثلاثةُ فتيان. تعلمتُ أن التاريخَ يا أصدقائي ليس حنيناً نبكي عليه… إنه وقودٌ نتحركُ به. من قرأ سيرةَ العظماءِ ثم جلسَ يبكي… أضاعَ نصفَ الدرس. اقرؤوها… ثم قوموا وابدؤوا بما بدؤوا به: وحّدوا قلوبَ من حولَكم.'}],
msg:'التاريخ وقود لا حنين: صلاح الدين وحّد القلوب قبل أن يرفع السيف — فابدأ أنت بتوحيد من حولك، لا بالبكاء وحده.',apply:'اقرأ هذا الأسبوع قصة حطين (٢٠ دقيقة تكفي) واحكها لأهلك على العشاء — وابدأ أنت بتوحيد قلوب من حولك: أصلح بين متخاصمين.'},

{n:72,t:'بحرُ العقبة',ic:'🌊',age:'١٧ سنة',loc:'العقبة — رحلة العصبة',corner:'sport',goal:'الرحلة الإيمانية: صحبة وسفر وتفكر — والسباحة في البحر امتحان المهارة الحقيقي',chars:['صلاح الدين','معاذ','حمزة','كريم','الشيخ محمود','سبّاح مبتدئ'],
scenes:[
{h:'م١ · خارجي — طريق الجنوب، انتخاب الأمير',d:'أول رحلة «رجال» بلا أهل: العصبة الأربعة + الشيخ محمود ومرشد، إلى العقبة. في محطة الانطلاق، يطبقون سنة السفر.',dlg:[['الشيخ محمود','قال ﷺ: إذا خرجَ ثلاثةٌ في سفرٍ فليؤمّروا أحدَهم. من الأمير؟ (الجميع يلتفت تلقائياً لصلاح الدين)'],['صلاح الدين','(يرفع يده معترضاً) أقترحُ معاذاً! هو أهدأُنا وأحكمُنا في القرارات. القائدُ الحقيقيُّ يا شباب يعرفُ متى يقودُ ومتى يُقاد — وأنا أتعلمُ الطاعةَ اليوم.'],['معاذ','(مندهش) أنا؟ لكنك أنت—'],['الشيخ محمود','(يبتسم) قبلتُ اقتراحَ صلاحِ الدين — وفيه درسٌ عظيم: من لا يحسنُ الطاعة، لا يحسنُ القيادة. معاذ أميرُكم — أطيعوهُ في المعروف.']],vo:'رشّحتُ معاذاً لا أنا — والناسُ استغربت. لكني تعلمتُ من سيرةِ القائدِ الذي أحملُ اسمَه: أنه أطاعَ قادةً قبلَهُ سنوات، وما استنكفَ أن يكونَ جندياً. القائدُ الذي لم يُطِعْ يوماً… لا يعرفُ ثقلَ الطاعةِ فيظلمُ جنودَه.'},
{h:'م٢ · خارجي — الطريق، دعاء السفر والصحبة',d:'مونتاج الرحلة: صحراء وجبال حمراء، السيارة تسير، دعاء السفر بأصواتهم مجتمعة، أناشيد، معاذ (الأمير) يقسم المهام بعدل: كريم مسؤول الطعام، حمزة الأغراض، صلاح الدين الملاحة والمواقيت. توقف لصلاة جمع في الطريق.',dlg:[['معاذ','(كأمير) نتوقفُ للصلاة هنا — الوقتُ دخل. كريم، جهّزِ الماءَ للوضوء. صلاح الدين، ابحثْ عن القبلة.'],['صلاح الدين','(يخرج بوصلة توم النحاسية — تلك التي أهداه إياها فوق الغيوم) البوصلةُ نفسُها يا شباب… أهداني إياها توم لئلا أضيع. وها هي تدلُّني على القبلة! (يبتسم) توم لا يعرفُ أنه اشترى لي بوصلةً تشيرُ إلى الله.']]},
{h:'م٣ · خارجي — بحر العقبة، موقف الإنقاذ',d:'البحر الأزرق الصافي. الفتيان يسبحون. صلاح الدين يلاحظ سبّاحاً مبتدئاً (فتى من مجموعة أخرى) جرفه تيار بعيداً ويكافح بذعر. لا يتهور — يطبق تدريب سنوات مانشستر: ينادي المرشد، يأخذ عوامة، يسبح بثبات، يقترب من خلف الغريق (لا من أمامه)، يهدئه ويسحبه للشاطئ بتقنية صحيحة.',dlg:[['صلاح الدين','(للغريق وهو يقترب من خلفه بهدوء) اهدأ… أمسكِ العوامة، لا تمسكْني. تنفسْ… أنا معك. بسم الله، نعودُ معاً.'],['المرشد','(على الشاطئ، بعد أن يخرجا) أحسنت! اقتربتَ من خلفِهِ لا من أمامِه… لو أمسكَك لأغرقكما معاً! أين تعلمتَ هذا؟'],['صلاح الدين','(يلهث) في نادي سباحةٍ صغيرٍ في مانشستر… وأنا في السادسة. (يبتسم) أبي قال يومَها: ربما تنقذُ به غريقاً يوماً. لم أصدّقْه… حتى اليوم.']],vo:'عشرُ سنينَ من السباحة… لهذه اللحظة. تذكرون قولَ أبي وأنا طفلٌ يشرقُ بالماء: «ربما تنقذُ به غريقاً»؟ الإعدادُ يا أصدقائي لا يعرفُ متى يُستدعى… لكنه حين يُستدعى، يفرقُ بين حياةٍ وموت. تدربوا وأنتم لا تعرفون لماذا… فاللهُ يعرفُ متى.'},
{h:'م٤ · خارجي — شاطئ الليل، مجلس التفكر',d:'ليل على الشاطئ. نار مخيم، والفتيان والشيخ حولها، والسماء مرصعة بنجوم العقبة الصافية والبحر يتنفس في الظلام. مجلس تفكر.',dlg:[['الشيخ محمود','انظروا هذا البحرَ في الظلام… وهذه النجوم. قال تعالى: أفلا ينظرون إلى الإبلِ كيف خُلقت، وإلى السماءِ كيف رُفعت. التفكرُ يا أبنائي عبادةٌ نسيَها الناس. فليقلْ كلٌّ منكم: ماذا يعلّمُهُ هذا البحرُ الليلة؟'],['كريم','يعلّمني أن ملكَ اللهِ واسع… وأن خلافاتِنا الصغيرةَ في المخيمِ أصغرُ من قطرةٍ فيه.'],['حمزة','يعلّمني الهدوء… أنا سريعُ الغضب، والبحرُ ثائرٌ نهاراً وساكنٌ ليلاً — أتعلمُ منه متى أثورُ ومتى أهدأ.'],['معاذ','يعلّمني عمقَه… ما تحتَ السطحِ أهم. الناسُ سطحٌ وأعماق.'],['صلاح الدين','(ينظر غرباً في العتمة) يعلّمني… أن خلفَ هذا الأفقِ المظلمِ أرضاً تنتظر. البحرُ نفسُهُ يا شباب يلمسُ شواطئَ فلسطين. الماءُ الذي أمامَنا… وصلَ يوماً إلى بحرِ غزةَ الذي حكى لي عنه أنس. كلُّ شيءٍ متصلٌ في ملكِ الله.']]},
{h:'م٥ · خارجي — الشاطئ، العهد المتجدد',d:'الفجر يقترب. العصبة تصلي الفجر جماعة على الشاطئ (معاذ يؤمّهم كأمير)، والبحر يعكس أول ضوء. بعد الصلاة، لحظة عهد.',dlg:[['صلاح الدين','هذه الرحلةُ علّمتني ثلاثاً: أطعتُ أميراً فتعلمتُ التواضع، وأنقذتُ غريقاً فعرفتُ ثمرةَ الإعداد، وتفكرتُ في البحرِ فصغُرتْ همومي. الرحلةُ يا شباب ليست ترفيهاً… إنها مدرسةٌ متنقلة.'],['الشيخ محمود','(يجمعهم) وأزيدُكم: هذه آخرُ رحلةٍ لي معكم بهذه الصحة، فأنا أضعف. فخذوا وصيةً: سافروا وتفكروا وتصاحبوا في الله — فالسفرُ يكشفُ معادنَ الرجال. من صحبتَهُ في سفرٍ فعرفتَهُ صبوراً كريماً لا يشكو… فأمسكْ به، فهو أخٌ في الله.'],['العصبة','(أيديهم فوق بعضها) عهدٌ متجدد: صحبةٌ في الله، إلى القدس.']],vo:'عدنا من العقبةِ أقوى إخوةً وأصفى قلوباً. وكانت — كما قال الشيخ — آخرَ رحلاتِنا معه. لكنه زرعَ فينا في تلك الليلةِ بذرةً: أن الأمةَ لا يبنيها أفرادٌ عظماءُ منفصلون… بل إخوةٌ صادقون متصلون. تصاحبوا في اللهِ يا شباب… فوحدَهُ الأخُ الصالحُ يذكّرُكَ حين تنسى، ويسندُكَ حين تقع.'}],
msg:'السفر يكشف معادن الرجال: من أطاع أميراً أحسن القيادة، والإعداد لا يعرف متى يُستدعى — والتفكر عبادة منسية.',apply:'في رحلتك القادمة مع أصدقاء: أمّروا أميراً وقسّموا المهام وادعوا دعاء السفر — وجرب «مجلس تفكر» ليلياً.'},

{n:73,t:'ميلادُ جيلِ القدس',ic:'🚩',age:'١٧ سنة',loc:'سطح بيت الجد',corner:'quds',goal:'من الحلم إلى التنظيم: تأسيس أول نواة — رؤية ونظام وأربعة أعضاء',chars:['صلاح الدين','معاذ','حمزة','كريم','الجد'],
scenes:[
{h:'م١ · خارجي — سطح بيت الجد، العرض على الورق',d:'السطح — مكان كل العهود. العصبة الأربعة مجتمعون. صلاح الدين يفرد لوحة كبيرة رسمها: مخطط منظم بعنوان «جيل القدس» وحوله خمسة أركان مرسومة كأعمدة.',dlg:[['صلاح الدين','منذ ليلةِ القدرِ وأنا أكتبُ هذا. اسمعوا: لماذا كلُّ نشاطاتِنا متفرقة؟ الحلقةُ هنا، والرياضةُ هناك، والخيرُ حين نتذكر. أقترحُ أن نجمعَها في نواةٍ منظمةٍ اسمُها «جيلُ القدس»: (يشير للأعمدة) عمودُ القرآنِ والعقيدة، عمودُ الجسدِ والرياضة، عمودُ العلمِ والتاريخ، عمودُ العملِ الخدميِّ الشهري، وعمودُ صندوقِ النصرة. لقاءٌ أسبوعيٌّ ثابت — كلُّ عمودٍ له وقتُه.'],['حمزة','(متحمس) فكرةٌ عظيمة! لكن… من أين المال؟ ومن أين الوقتُ ونحن مقبلون على الجامعة؟ وهل نستمرُّ أم نتحمسُ شهراً ثم نفتر كعادةِ المشاريع؟']]},
{h:'م٢ · خارجي — السطح، النقاش الجاد',d:'نقاش حقيقي ناضج — لا حماس أعمى.',dlg:[['صلاح الدين','أسئلةٌ ممتازةٌ يا حمزة — وهذا الفرقُ بين حلمٍ ومشروع. المال: كلٌّ يدفعُ اشتراكاً رمزياً + صندوقُ الكعكِ الذي أتقنَهُ كريم. الوقت: ساعتان أسبوعياً فقط — لا نطلبُ المستحيل. والاستمرار (وهنا الأهم): قاعدةُ أمي — أحبُّ الأعمالِ أدومُها وإن قل. لا نبدأ ضخماً ثم ننهار… نبدأ صغيراً ثابتاً ثم نكبر.'],['معاذ','وأزيدُ شرطاً: نظامٌ مكتوب. أميرٌ ينتخب كلَّ سنة، ومحضرُ كلِّ لقاء، وأهدافٌ نراجعها. الفوضى قتلتْ ألفَ مشروعِ خير.'],['كريم','(بحماس هادئ) وأنا أتكفلُ بأن نصلَ من هم مثلي — فتيانُ المخيمِ الذين لا نادي لهم ولا فرصة. جيلُ القدسِ يجبُ أن يضمَّ الغنيَّ والفقير، ابنَ المدينةِ وابنَ المخيم.']]},
{h:'م٣ · خارجي — السطح، القاعدة الذهبية',d:'صلاح الدين يكتب على أعلى اللوحة القاعدة المؤسِّسة، ويشرحها.',dlg:[['صلاح الدين','(يكتب بخط كبير) القاعدةُ الذهبية: «نبني الجيلَ الذي يستحقُّ النصر… قبل أن نطلبَ النصر». اسمعوا — القائدُ الذي أحملُ اسمَه لم يحررِ القدسَ بجيشٍ جمعَهُ في شهر… حررها بجيلٍ رباه في عقود: على العقيدةِ والقرآنِ والقوةِ والوحدة. النصرُ يا إخوتي ثمرة — والثمرةُ لا تُقطَفُ من شجرةٍ لم تُغرَس. مهمتُنا ليست أن نفتحَ القدسَ غداً… مهمتُنا أن نصنعَ الجيلَ الذي يفتحُها — نحن أو من بعدَنا. نزرعُ… ومن يقطفُ أمرُهُ إلى الله.'],['حمزة','(هادئاً لأول مرة) يعني قد لا نرى الثمرة بأنفسنا…'],['صلاح الدين','قد لا نراها. الذي غرسَ زيتونةَ جدي ما أكلَ من زيتِها — أكلْنا نحن. أتوقفُ الغارسُ عن الغرسِ لأنه لن يأكل؟ نغرسُ لله… لا لأنفسنا.']]},
{h:'م٤ · خارجي — السطح، مباركة الجد والمقر',d:'الجد — أضعف مما كان، متوكئ بشدة — يصعد السطح مسنوداً من حفيده. جاء ليشهد التأسيس.',dlg:[['الجد','(يتأمل اللوحة طويلاً، بصوت واهن لكن مضيء) خمسون سنةً وأنا أحملُ مفتاحاً وأنتظر… ظننتُ أني سأموتُ والبابُ مغلق. واليومَ أرى على سطحِ بيتي… جيلاً يولد. (يلتفت للفتية الأربعة) اسمعوا وصيةَ عجوزٍ قربَ الرحيل: القدسُ لن تُفتَحَ بالشعاراتِ ولا بالدموع… ستُفتَحُ بأمثالِكم — إن صدقتُم وثبتُّم وربّيتُم من بعدَكم. (يشير لغرفة السطح) هذه الغرفةُ… مقرُّكم الأول. هبةٌ مني لجيلِ القدس. عمّروها بالقرآنِ والعلم.'],['صلاح الدين','(يقبّل رأس جده) وأنتَ أولُ الشهود يا جدي… سجّلْ أسماءَنا بيدك.']]},
{h:'م٥ · خارجي — السطح، الميثاق والأفق',d:'الجد يجلس، والفتية يمدون له دفتراً جديداً. بيده المرتجفة يسجل أول أربعة أسماء تحت عنوان «جيل القدس — المؤسسون». ثم يوقّع كل واحد. اللقطة الختامية: الأربعة واقفون عند حافة السطح، والدفتر مفتوح، والكاميرا ترتفع ببطء من السطح نحو الأفق الغربي حيث تلوح تلال فلسطين البعيدة.',dlg:[['الجد','(يكتب ببطء) صلاح الدين… معاذ… حمزة… كريم. (يرفع القلم) أربعة. بدأ رسولُ اللهِ ﷺ بأقلَّ من هذا في دارِ الأرقم… والأربعةُ الصادقون خيرٌ من أربعةِ آلافٍ متفرقين.'],['صلاح الدين','(للعصبة، وأيديهم فوق الميثاق) نعاهدُ اللهَ: نبني أنفسَنا وجيلَنا، ونثبتُ ما حيينا، ونسلّمُ الرايةَ لمن بعدَنا إن لم ندركِ الفتح. جيلُ القدس… يبدأُ اليوم.'],['العصبة','(معاً) شهدَ اللهُ.']],vo:'أربعةُ فتيانٍ على سطحِ بيتٍ في عمّان… ودفترٌ فيه أربعةُ أسماء. تضحكون كما ضحكتم من صحنِ الكعكِ ومن حديقةِ الأيدي الصغيرة؟ لا تضحكوا. فمن هذا السطحِ الصغير — ومن هذه الأربعة — سيكبرُ ما ستشاهدونه في الحلقاتِ الأخيرة: جيلٌ في عشرين عاصمة. كلُّ نهرٍ يا أصدقائي… كان يوماً نقطةَ ماءٍ قررتْ أن تجري.'}],
msg:'نبني الجيل الذي يستحق النصر قبل أن نطلبه: النصر ثمرة لا تُقطف من شجرة لم تُغرس — والأربعة الصادقون خير من آلاف متفرقين.',apply:'أسس نواتك: اجمع ٣ أصدقاء وحددوا لقاء أسبوعياً ثابتاً فيه: آيات تُحفظ، ورياضة، وقصة بطل، وعمل خير شهري.'},

{n:74,t:'امتحاناتُ السنةِ الأخيرة',ic:'📘',age:'١٧ سنة ونصف',loc:'مدرسته — التوجيهي',corner:'academy',goal:'الإتقان في الدراسة عبادة: التفوق للأمة لا للأنا — ورفض شبكات الغش مهما كان الثمن',chars:['صلاح الدين','أيوب','مجموعة الدراسة','زميل التسريبات'],
scenes:[
{h:'م١ · داخلي — غرفته، خطة السنة الحاسمة',d:'سنة التوجيهي. صلاح الدين أمام جدول كبير على جداره: مواد الهندسة تحتاج معدلاً عالياً. يبني نظاماً محكماً.',dlg:[['صلاح الدين','(يكتب الجدول لأبيه) قرارُ ليلةِ القدرِ يبدأ هنا يا بابا: الهندسة. والهندسةُ تحتاجُ معدلاً عالياً. خطتي: بركةُ الفجرِ للمراجعة — أصعبُ المواد بعد صلاةِ الفجر حين يكونُ العقلُ أصفى، وجدولٌ يوميٌّ صارم، ورياضةٌ ثلاثَ مراتٍ أسبوعياً تحفظُ عقلي من الإرهاق.'],['أيوب','خطةٌ ممتازة. لكن تذكّرْ نيتَك: لمَ تريدُ التفوق؟'],['صلاح الدين','ليس للتباهي بالمعدل يا بابا… بل لأدخلَ الهندسةَ فأبنيَ للأمة. التفوقُ لجيلِ القدس، لا لأناي.'],['أيوب','(يبتسم) إذن ذاكِرْ… فالنيةُ الصالحةُ تجعلُ من كلِّ مسألةِ رياضياتٍ عبادة.']]},
{h:'م٢ · داخلي — المكتبة، مجموعة الدراسة الجامعة',d:'صلاح الدين يقود مجموعة دراسة في المكتبة — لكنه لا يجمع المتفوقين فقط، بل يضم زملاء ضعافاً أيضاً.',dlg:[['زميل متفوق','لماذا تدخلُ معنا الضعاف؟ سيبطئوننا! المجموعةُ للأقوياء فقط لنرفعَ مستوانا.'],['صلاح الدين','القائدُ يرفعُ الجميعَ يا صاحبي — ثم إن شرحي لكم يثبّتُ علمي أنا! من علّمَ فهم مرتين. لن أصعدَ وحدي وأتركَ صفي خلفي — هذا ليس نجاحاً، هذا أنانية. (لزميل ضعيف) تعالَ يا محمود، اجلسْ هنا — سنبدأُ من حيثُ توقفتَ أنت.']]},
{h:'م٣ · داخلي — الصف، ليلة التسريب',d:'قبل الامتحان بيومين. زميل يقترب همساً — عرض شبكة تسريبات يشترك فيها كثيرون.',dlg:[['زميل التسريبات','صلاح الدين… عندنا أسئلةُ الامتحانِ الحقيقية، مسربةٌ من مصدرٍ موثوق. الجميعُ مشترك — معدلٌ مضمونٌ بلا تعب! أنتَ ذكيٌّ، ستفهمُ أن رفضَها حماقة. مئةُ دينارٍ فقط ومقعدُ الهندسةِ مضمون.'],['صلاح الدين','(يتوقف — الإغراء حقيقي: مقعد حياته على المحك، والجميع يفعلها) اسمعْ جيداً: أنا حافظُ قرآن. والقرآنُ الذي في صدري يقول: من غشَّنا فليسَ منا. أتريدُني أن أدخلَ الهندسةَ بمقعدٍ حرام، ثم أبني للأمةِ على أساسٍ من غش؟ المعدلُ الذي يُبنى على كذبة… ينهارُ كبيتِ العنكبوت. لا — وألفُ لا. وانصحُكَ: انسحبْ قبل أن تُكشَفَ الشبكةُ وتضيعَ سنتُكَ كلُّها.'],['زميل التسريبات','(ساخراً) خسارتُك! ستندمُ حين ترى معدلاتِنا.'],['صلاح الدين','(بهدوء) الندمُ الحقيقيُّ يا صاحبي… يأتي متأخراً. سنرى.']]},
{h:'م٤ · داخلي — قاعة الامتحان، طمأنينة النظيف',d:'قاعة الامتحان. توتر عام. صلاح الدين يجلس هادئاً، يستعيذ، «بسم الله»، ويكتب بعلمه. حوله بعض المشتركين في الشبكة متوترون (تغيرت بعض الأسئلة!). صلاح الدين يجيب بثقة من ذاكر بنفسه.',vo:'دخلتُ الامتحانَ وقلبي مطمئن — لا أخافُ رقيباً ولا كشفَ شبكة، لأني لا أحملُ إلا علمي. ورأيتُ المشتركين في الغشِّ يرتجفون: تغيرتْ أسئلةٌ كثيرة، وانكشفتِ الشبكةُ جزئياً قبل الامتحانِ بيوم. طمأنينةُ النظيفِ يا أصدقائي… لا يشتريها مالٌ ولا تسريب.'},
{h:'م٥ · داخلي — البيت، النتيجة والباب',d:'يوم النتائج. العائلة مجتمعة. صلاح الدين يفتح الموقع بيد مرتجفة… ثم يخرّ ساجداً. معدل يضعه في العشرة الأوائل — وقبول في كلية الهندسة.',dlg:[['صلاح الدين','(يرفع رأسه من السجود) الحمدُ لله! من العشرةِ الأوائل… ومقعدُ الهندسةِ لي — نظيفٌ حلال!'],['أيوب','(يعانقه) مبروك يا مهندسَ الأمة! وأتعرفُ الخبرَ الآخر؟ شبكةُ التسريباتِ كُشفتْ كاملة — أُلغيتْ نتائجُ المشتركين وأُوقفوا سنة.'],['صلاح الدين','(بحزن حقيقي لا شماتة) الزميلُ الذي عرضَ عليّ… ضاعتْ سنتُه؟ (يخرج هاتفه) سأتصلُ به — لا لأقولَ «قلتُ لك»، بل لأعرضَ مساعدتَهُ في العامِ القادم. سقطَ مرة… لا يعني أن نتركَهُ يسقطُ للأبد.'],['مريم','(تهمس لأيوب) انظر… يفوزُ نظيفاً، ثم يمدُّ يدَهُ لمن أرادَ إسقاطَه. هذا ابنُنا.']],vo:'دخلتُ الهندسةَ بمقعدٍ نظيف… وبقلبٍ مطمئن. وتعلمتُ أن الإتقانَ في الدراسةِ عبادة، وأن الدرجةَ المبنيةَ على غشٍّ كالبناءِ على رمل: يبدو شامخاً، ثم ينهارُ عند أولِ اختبارٍ حقيقي. اجتهدوا نظافاً يا شباب… فالنجاحُ الحلالُ وحدَهُ يُبنى عليه.'}],
msg:'الدرجة المبنية على غش كالبناء على رمل: التفوق للأمة لا للأنا — والقائد يرفع صفه معه ولا يصعد وحده.',apply:'اصنع «بركة الفجر»: ذاكر أصعب موادك بعد صلاة الفجر أسبوعاً كاملاً — وقس الفرق بنفسك.'},

{n:75,t:'رحيلُ حاملِ المفتاح',ic:'🍂',age:'١٧ سنة ونصف',loc:'بيت الجد — عمّان',corner:'aqeeda',goal:'الموت على ذكر الله غاية العمر: وداع الجد — والإرث الحقيقي وصية لا مال',chars:['صلاح الدين','الجد','أيوب','مريم','العائلة','أهل المخيم'],
scenes:[
{h:'م١ · داخلي — غرفة الجد، علامات الرحيل',d:'الجد طريح الفراش — مرضه الأخير. لكنه هادئ، صافٍ، يكثر الاستغفار. يرتب أوراقه بيده الضعيفة، يوزع كلماته كوصايا. صلاح الدين يجلس عند رأسه.',dlg:[['الجد','(بصوت واهن، يبتسم) لا تحزنْ على وجهي هكذا يا حاملَ الاسم… العجوزُ الذي عاشَ ثمانين سنةً ورأى حفيدَهُ يحفظُ القرآنَ ويؤسسُ جيلاً… ماذا يريدُ أكثر؟ أنا راضٍ يا صلاح الدين… راضٍ كلَّ الرضا. الموتُ ليس نهايةً يا بني… إنه سفرٌ إلى من نحب. وأنا مشتاقٌ للقاءِ ربي، ولقاءِ أهلي الذين سبقوني، ولقاءِ… القدسِ التي لم أرَها منذ سبعين سنة، لعلي أراها من فوق.'],['صلاح الدين','(يمسك يده، يكتم دمعه) جدي… لا تتكلمْ هكذا. ستقوم، وسنسقي الزيتونةَ معاً.'],['الجد','(يربت يده) الزيتونةُ لك الآن يا بني… اسقِها عني.']]},
{h:'م٢ · داخلي — غرفة الجد، مجالس الوصايا',d:'مونتاج أيام الوداع: العائلة تتناوب عنده. لكل حفيد كلمة تخصه — ليوسف عن القوة، لشام عن العلم. مريم تطعمه، أيوب يقرأ عنده. والجد يوزع أوراقاً صغيرة مكتوبة.',dlg:[['الجد','(ليوسف) يا يوسف — كن ساعدَ أخيك الأيمن كما وعدتَ يومَ وُلدت… جيلُ القدسِ يحتاجُ قوتَك. (لشام) يا شام — سُمّيتِ على أرضٍ مباركة، فكوني معلمةً للصغيرات كأمك. (لمريم) يا بنتي — ربّيتِ لي رجالاً… جزاكِ اللهُ عني خيرَ الجزاء. (لأيوب) يا ولدي — أحسنتَ نقلَ الشجرةِ إلى أرضِها… فأثمرت.']]},
{h:'م٣ · داخلي — غرفة الجد، ليلة يس',d:'ليلة ثقيلة — يشعر الجميع أنها قريبة. الجد يطلب طلباً أخيراً.',dlg:[['الجد','(همساً لصلاح الدين) اقرأ عندي… يس. بصوتِكَ الذي أوصلتُهُ لحلقةِ الشيخِ محمود أولَ يوم. أريدُ أن يكونَ آخرُ ما أسمعُهُ من الدنيا… كلامَ ربي، بصوتِ حفيدي الحافظ.'],['صلاح الدين','(يفتح المصحف الأزرق، صوته يرتجف ثم يثبت) بسم الله الرحمن الرحيم. يس. والقرآنِ الحكيم…'],['الجد','(عيناه مغمضتان، شفتاه تتحركان مع الآيات، وجهه يزداد سكينة، ودمعة تنساب)'],['صلاح الدين','(يصل «سلامٌ قولاً من ربٍّ رحيم» ويرفع عينيه — الجد يبتسم بعينين مغمضتين)']],vo:'قرأتُ يس عند رأسِ الرجلِ الذي أوصلني لحلقةِ القرآنِ أولَ يوم… فكان القرآنُ أولَ ما جمعَنا وآخرَ ما جمعَنا. وشعرتُ أن الدائرةَ تكتمل.'},
{h:'م٤ · داخلي — غرفة الجد، لحظة الرحيل',d:'الفجر يقترب. أذان الفجر يرتفع من مسجد الحي. الجد يفتح عينيه لحظة، ينظر لصلاح الدين، وشفتاه تتحركان.',dlg:[['الجد','(بآخر نفَسٍ، همساً واضحاً) أشهدُ أن لا إلهَ إلا الله… وأشهدُ أن محمداً رسولُ الله… (يوصي بإصبعه للمفتاح على صدر حفيده)… لا تسلّمْهُ إلا لبابِه… (يبتسم، وتسكن يده)'],['صلاح الدين','(يضع يده على عيني جده، دموعه تنهمر بصمت) إنا للهِ وإنا إليه راجعون… على الشهادةِ يا جدي… كما عشتَ متَّ. (يقبّل جبينه) وعدُك أمانة… لن أسلّمَهُ إلا لبابِه.']],vo:'ماتَ جدي فجراً، وشفتاهُ تنطقانِ الشهادة — كما تمنى، وكما عاش. من عاشَ على شيءٍ ماتَ عليه، ومن ماتَ على شيءٍ بُعثَ عليه. جدي عاشَ ذاكراً… فماتَ ذاكراً… وسيُبعثُ — بإذن الله — ذاكراً.'},
{h:'م٥ · خارجي — الجنازة، السر المكشوف',d:'يوم الجنازة. مسجد الحي يمتلئ… ثم يفيض بمن لا يعرفهم أحد من الحي: مئات من أهل المخيم — رجال ونساء وأطفال، بينهم كريم وأمه — جاؤوا كلهم. العائلة مذهولة.',dlg:[['أيوب','(مندهشاً لكريم) كلُّ هؤلاء… من المخيم؟! من أينَ يعرفون أبي؟'],['كريم','(بعينين دامعتين) يا عمي… جدُّكم عبد القادر كان يأتي المخيمَ كلَّ شهرٍ من ثلاثين سنة! يدفعُ إيجاراتِ العاجزين سراً، ويزوّجُ الأيتام، ويكفلُ طلابَ العلم — ويوصي كلَّ واحدٍ ألا يخبرَ أحداً. نحن لم نعرفْ إلا اليومَ أنه جدُّ صلاح الدين… كان يقولُ فقط: أنا رجلٌ من القدس، أؤدي بعضَ حقِّها.'],['صلاح الدين','(يبكي بين الحشد) صدقةُ السرِّ… ثلاثون سنة، ولم نعلم! تشيّعُهُ اليومَ مدينةٌ كاملةٌ من الناسِ الذين سترَ اللهُ عليهم بيدِه. (يرفع يديه) اللهم كما سترَ عبادَك… استرْهُ برحمتِك.']],vo:'كشفتِ الجنازةُ سرَّ جدي: صدقةٌ خفيةٌ ثلاثين سنة، تشيّعُهُ اليومَ بمئاتِ الوجوه. وفهمتُ أخيراً لماذا كان قلبُهُ نظيفاً كما اشترطَ يومَ سلّمني المفتاح: من زرعَ الخيرَ سراً كلَّ عمرِه… طهُرَ قلبُهُ لحملِ الأمانات. يا من تريدون قلوباً نظيفةً تليقُ بالأبواب الكبرى: ابدؤوا بصدقةِ السرِّ… فهي التي تغسلُ القلبَ حين لا يراكم أحدٌ إلا الله.'}],
msg:'من عاش على شيء مات عليه: الجد عاش ذاكراً فمات على الشهادة — وصدقة السر ثلاثين سنة شيّعتها مدينة وطهّرت قلباً للأمانة.',apply:'اتصل بجدك أو جدتك اليوم — وإن كانا قد رحلا فادعُ لهما وتصدق عنهما: «أو ولد صالح يدعو له».'},

{n:76,t:'الوصيةُ المكتوبة',ic:'📜',age:'١٨ سنة إلا أياماً',loc:'غرفة السطح — مقر جيل القدس',corner:'parents',goal:'تحويل الحزن إلى طاقة: وصية الجد خارطة طريق — والحداد الإيجابي عمل يواصل أثر الميت',chars:['صلاح الدين','أيوب','مريم','يوسف','شام','العصبة'],
scenes:[
{h:'م١ · داخلي — البيت، فتح الظرف',d:'بعد الأربعين. العائلة مجتمعة. أيوب يحمل ظرفاً تركه الجد، عليه بخطه: «يُفتح بعد أربعين يوماً — حين تهدأ الدموع ويبدأ العمل».',dlg:[['أيوب','(يفتح الظرف بيد مرتجفة) تركَ لكلٍّ منا سطراً… ولصلاحِ الدين صفحةً كاملة. أبي رتّبَ حتى وداعَه.'],['يوسف','(يقرأ سطره) «يا يوسف: القوةُ أمانة — كن درعَ أخيك». (يمسح دمعته) وعدتُهُ يا جدي.'],['شام','(تقرأ سطرها) «يا شام: علّمي الصغيرات… فأنتِ أرضٌ مباركة تُنبتُ ما يُزرَعُ فيها».'],['مريم','(سطرها) «يا مريم: ما ربّيتِ أولاداً… ربّيتِ أمة». (تبكي)']]},
{h:'م٢ · داخلي — غرفة السطح، الوصية المتناوبة',d:'صلاح الدين يصعد وحده إلى غرفة السطح (مقر جيل القدس) ليقرأ صفحته. المشهد يُروى بتقنية مؤثرة: يقرأ صلاح الدين سطراً بصوته، ثم نسمع صوت الجد (فلاش باك صوتي) يكمل — الصوتان يتعانقان.',dlg:[['صلاح الدين','(يقرأ) «يا حاملَ الاسمين الثقيلين…»'],['الجد (صوته)','«…صلاحَ الدينِ حاملَ اسمِ البطل، وحاملَ مفتاحِ الجد. لا تبكِ على العجوزِ طويلاً — فقد عشتُ حتى رأيتُ فيكَ ما تمنيتُ يومَ سمّيتُك. أوصيك بثلاث، رتّبْها كما رتّبتُها: أمكَ وأبوكَ أولاً — فرضاهما بابُك إلى الجنةِ وإلى النصر. ثم أمتُك — فأنتَ لها لا لنفسِك. ثم المفتاح — لا تسلّمْهُ إلا لبابِه، أو لجيلٍ أنقى منك إن سبقتَهُ إلى الله».'],['صلاح الدين','(يكمل القراءة، دموعه على الورقة) «واجعلْ جيلَ القدسِ صدقتي الجارية… فما بنيتَ من خيرٍ يصلُني في قبري. وازرعْ عن كلِّ سنةٍ من عمري زيتونة — ثمانين زيتونة — تُظلِّلُ من يأتي بعدَك، كما أظلَّتْكَ زيتونتي».']]},
{h:'م٣ · داخلي — البيت، قرار الوقف',d:'العائلة تجتمع لتقرر مصير بيت الجد. صلاح الدين يقترح، والجميع يتفق.',dlg:[['صلاح الدين','بيتُ جدي… أقترحُ أن نوقفَهُ صدقةً جارية: حديقتُهُ تصيرُ حديقةَ الحي، وصالتُهُ قاعةَ تحفيظٍ للأطفال، وغرفةُ السطحِ مقرَّ جيلِ القدس الدائم. لا نبيعُهُ ولا نتوارثُه… نجعلُهُ يعملُ للجدِّ بعد موتِه.'],['أيوب','(متأثراً) هذا أعظمُ ميراثٍ نتركُهُ لأبي — لا حجراً نتقاسمُه، بل منارةً تعملُ باسمِه. موافق.'],['مريم ويوسف وشام','(معاً) موافقون.'],['صلاح الدين','إذن نسجّلُهُ وقفاً باسمِ «عبد القادر — حامل المفتاح». اسمُهُ سيبقى يُذكَرُ في كلِّ آيةٍ تُحفَظُ في صالتِه… وكلِّ طفلٍ يلعبُ في حديقتِه.']]},
{h:'م٤ · خارجي — حديقة البيت، غرس الزيتونة الأولى',d:'صلاح الدين ويوسف وشام في الحديقة، حول الزيتونة العتيقة. صلاح الدين يحمل شتلة زيتون صغيرة — الأولى من ثمانين — ويحفر بجانب الشجرة الأم.',dlg:[['صلاح الدين','(يغرس الشتلة، الثلاثة أيديهم على التراب معاً) زيتونةٌ عن كلِّ سنةٍ من عمرِ جدي… هذه الأولى. (يسقيها بالدلو نفسه الذي كان الجد يسقي به) بسم الله… يا جدي، غرستَ لي فأظللتَني، وأغرسُ لمن يأتي بعدي.'],['شام','(الصغيرة) وأنا سأسقيها كلَّ يومٍ يا صلاح الدين! مثلما كان جدي يعلّمك!'],['يوسف','ونعدُّ معاً حتى الثمانين — زيتونةً كلَّ أسبوع، حتى تصيرَ حديقةُ جدي غابةً باسمِه.']],vo:'غرسْنا الزيتونةَ الأولى بأيدينا الثلاثة… وأكملْنا الثمانين في عام. صارتْ حديقةُ جدي بستانَ زيتونٍ يحملُ اسمَه — يأكلُ من زيتِهِ فقراءُ الحي، ويلعبُ تحتَ ظلِّهِ أطفالُ القاعة. وهكذا حوّلنا الحزنَ إلى غرس… والدمعةَ إلى شتلة.'},
{h:'م٥ · داخلي — غرفة السطح، الحداد الإيجابي',d:'مقر جيل القدس. العصبة الأربعة مجتمعون، ووصية الجد معلقة على الجدار في إطار. صلاح الدين يقف أمامهم.',dlg:[['صلاح الدين','(يشير للوصية) جدي أوصى أن يكونَ جيلُ القدسِ صدقتَهُ الجارية. فلن نحزنَ عليه حزناً يقعدُنا… سنحزنُ عليه حزناً يحرّكُنا! هذا هو الحدادُ الحقيقيُّ على العظماء: أن نكملَ طريقَهم لا أن نبكيَ على قبورِهم. من اليوم، كلُّ إنجازٍ لجيلِ القدس… نُهديهِ لروحِ حاملِ المفتاح.'],['معاذ','وكلُّ ختمةِ طفلٍ في قاعتِه… حسنةٌ في ميزانِه.'],['حمزة','وكلُّ زيتونةٍ نغرسُها… صدقةٌ جارية.'],['كريم','(بصوت متأثر) جدُّكَ دفعَ إيجارَ بيتِنا سنواتٍ ونحن لا نعلم… فلأجعلنَّ من نفسي ما كان: أخدمُ في الخفاءِ ما حييت.'],['صلاح الدين','(يرفع يده والجميع فوقها) على روحِ عبد القادر… حاملِ المفتاح… نكمل. جيلُ القدسِ لا يتوقف.']],vo:'انتهتْ مرحلةُ بناءِ الفارس — بأثقلِ فقدٍ وأعظمِ درس: أن الموتَ لا يوقفُ المشروع… إن كان المشروعُ أكبرَ من صاحبِه. رحلَ جدي جسداً… وبقيَ في كلِّ زيتونةٍ وكلِّ طفلٍ وكلِّ خميس. فيا من فقدَ عزيزاً: لا تدفنْ أحلامَهُ معه… أكمِلْها، فتصيرَ حياتُكَ امتداداً لحياتِه. وهكذا لا يموتُ الصالحون حقاً… بل ينتقلون من العملِ بأيديهم… إلى العملِ بأيدينا.'}],
msg:'الحداد الحقيقي على العظماء إكمال طريقهم لا البكاء على قبورهم: حوّل الحزن غرساً والدمعة شتلة — فلا يموت الصالحون بل ينتقلون للعمل بأيدينا.',apply:'اسأل والديك: ما الأثر الذي يتمنيان أن يبقى لهما؟ — وابدأ لهما «صدقة جارية» صغيرة اليوم ولو مصحفاً يُقرأ منه.'}
]});
